const money=x=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(x??0)+' ₽';
const dateLong=x=>new Date(x).toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'});
const dateShort=x=>new Date(x+'T12:00').toLocaleDateString('ru-RU',{day:'numeric',month:'short'}).replace('.','');
