const nav=[['overview','grid','Обзор'],['events','calendar','Мероприятия'],['tasks','tasks','Задачи'],['program','list','Программа'],['guests','users','Участники'],['messages','mail','Рассылки'],['team','team','Команда'],['catalog','pin','Каталог'],['chat','chat','Чат команды'],['assistant','spark','ИИ-ассистент'],['files','folder','Файлы'],['budget','wallet','Бюджет'],['calendar','calendar','Календарь'],['analytics','chart','Аналитика'],['survey','poll','Опрос гостей']];
