async function api(path,method='GET',data){const response=await fetch('/api'+path,{method,headers:{'X-EventGo':'1',...(data===undefined?{}:{'Content-Type':'application/json'})},body:data===undefined?undefined:JSON.stringify(data)});const result=await response.json();if(!response.ok){if(response.status===401&&s.user){s.user=null;renderLogin();}throw Object.assign(new Error(result.error||'Не удалось выполнить запрос.'),{status:response.status});}return result;}
function toast(text,error=false){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').className='show'+(error?' error':'');toastTimer=setTimeout(()=>$('#toast').className='',4500);}
const revealMotionOk=()=>!matchMedia('(prefers-reduced-motion: reduce)').matches;
const revealObserver=revealMotionOk()?new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;entry.target.classList.add('is-in');revealObserver.unobserve(entry.target);}},{threshold:.12,rootMargin:'0px 0px -24px 0px'}):null;
function prepareReveals(root=document){if(!revealObserver)return;root.querySelectorAll('.metric,.panel,.event-card,.person-card,.catalog-card,.poster-hero,.wallet-card,.ai-helper-card').forEach(el=>{if(el.dataset.reveal)return;el.dataset.reveal='1';const rect=el.getBoundingClientRect();if(rect.top<innerHeight*.92&&rect.bottom>40){el.classList.add('reveal','is-in');return;}el.classList.add('reveal');revealObserver.observe(el);});}
let revealTimer=0;const revealWatch=new MutationObserver(()=>{clearTimeout(revealTimer);revealTimer=setTimeout(()=>prepareReveals($('#app')||document),40);});
function startRevealWatch(){const app=$('#app');if(!app||!revealObserver)return;revealWatch.observe(app,{childList:true,subtree:true});prepareReveals(app);}
function openModal(title,content,{submit='',onSubmit=null,wide=false}={}){closeModal();modalSubmit=onSubmit;const m=$('#modal');m.style.width=wide?'min(760px,calc(100vw - 30px))':'';m.innerHTML=`<${onSubmit?'form id="modal-form"':'div'}><div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button type="button" class="icon-button" data-action="close" aria-label="Закрыть">${icon('close')}</button></div><div class="modal-body">${content}<p class="form-error" role="alert"></p></div>${onSubmit?`<div class="modal-footer"><button type="button" class="button secondary" data-action="close">Отмена</button><button class="button" type="submit">${esc(submit||'Сохранить')}</button></div>`:''}</${onSubmit?'form':'div'}>`;m.showModal();}
function closeModal(){if(cleanupModal){cleanupModal();cleanupModal=null;}$('#modal').close();modalSubmit=null;}
$('#modal').addEventListener('cancel',()=>{if(cleanupModal){cleanupModal();cleanupModal=null;}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
function field(label,name,value='',type='text',opts={}){const control=type==='textarea'?`<textarea name="${name}" ${opts.required===false?'':'required'} maxlength="${opts.max||4000}" placeholder="${esc(opts.placeholder||'')}">${esc(value)}</textarea>`:type==='select'?`<select name="${name}" ${opts.required===false?'':'required'}>${opts.options.map(([v,l])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`).join('')}</select>`:`<input type="${type}" name="${name}" value="${esc(value)}" ${opts.required===false?'':'required'} ${type==='number'?`min="${opts.min??0}" max="10000000000" step="${opts.step||'1'}"`:`maxlength="${opts.max||500}"`} placeholder="${esc(opts.placeholder||'')}" ${type==='password'?'autocomplete="current-password"':''}>`;return `<label class="field ${opts.full?'full':''}"><span>${esc(label)}${opts.required===false?'':' <span aria-hidden="true">*</span>'}</span>${control}${opts.hint?`<small>${esc(opts.hint)}</small>`:''}</label>`;}
function formObject(form){return Object.fromEntries(new FormData(form));}
async function reload(render=true){s.portfolioFresh=false;s.notifications=await api('/notifications').catch(()=>s.notifications);if(isOrg()&&!s.mail)s.mail=await api('/mail').catch(()=>null);s.events=await api('/events');if(!s.events.some(e=>e.id===s.eventId))s.eventId=s.events.find(e=>e.title==='IT-Форум 2026')?.id||s.events[0]?.id;if(s.eventId){localStorage.setItem('eventgo-event',s.eventId);s.data=await api('/events/'+s.eventId);}else s.data=null;if(render)renderShell();}
async function saved(path,method,data,message='Изменения сохранены'){const result=await api(path,method,data);closeModal();await reload();toastWithWarnings(message,result);}
function toastWithWarnings(message,result){const warnings=result?.warnings||[];if(warnings.length)toast(`${message}. Внимание: ${warnings.join(' ')}`,true);else toast(message);}
function yakutskNow(){return new Date(Date.now()+9*3600000).toISOString().slice(0,16);}
function formatDay(day){return day.split('-').reverse().join('.');}
function checkDates(){const w=$('#modal .date-warning');if(!w)return;const form=w.closest('form');const messages=[];if(w.dataset.check==='event'&&form?.starts_at?.value){const v=form.starts_at.value,end=eventEnd({starts_at:v,ends_at:form.ends_at?.value||''});if(form.ends_at?.value&&form.ends_at.value<=v)messages.push('Окончание должно быть позже начала.');else if(end<yakutskNow())messages.push('Эта дата уже прошла. Проверьте год, день и время. Прошедшее мероприятие сохранится со статусом «Завершено».');const late=(s.data?.event?.id===Number(w.dataset.eventId)?s.data.tasks:[]).filter(t=>t.status!=='done'&&t.due_date>end.slice(0,10)).length;if(late)messages.push(`Незавершённых задач со сроком позже этой даты: ${late}.`);}
 if(w.dataset.check==='task'&&form?.due_date?.value&&w.dataset.eventDate&&form.due_date.value>w.dataset.eventDate)messages.push(`Срок позже даты мероприятия (${formatDay(w.dataset.eventDate)}). Задача может не успеть к событию.`);
 w.textContent=messages.join(' ');w.hidden=!messages.length;}
document.addEventListener('input',e=>{if(e.target.closest?.('#modal'))checkDates();});
document.addEventListener('change',e=>{if(e.target.closest?.('#modal'))checkDates();});
function eventSelect(){return s.events.length?`<select class="event-switch" aria-label="Выбрать мероприятие" data-change="event">${s.events.map(e=>`<option value="${e.id}" ${e.id===s.eventId?'selected':''}>${esc(e.title)}</option>`).join('')}</select>`:'';}
function renderShell(){const current=allowedNav().find(n=>n[0]===s.view)||nav[0];$('#app').innerHTML=`<div class="mobile-overlay ${s.menu?'open':''}" data-action="menu"></div><aside class="sidebar ${s.menu?'open':''}">${brand()}<p class="nav-label">РАБОЧЕЕ ПРОСТРАНСТВО</p><nav class="nav-list" aria-label="Основная навигация">${allowedNav().map(([key,ic,label])=>`<button class="nav-item ${key===s.view?'active':''}" data-action="nav" data-view="${key}" ${key===s.view?'aria-current="page"':''}>${icon(ic)}${label}${key==='tasks'&&s.data?.event.tasks.overdue?`<span class="count">${s.data.event.tasks.overdue}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="workspace"><div class="workspace-icon">НТ</div><div><strong>Команда «Не по ТЗ»</strong><span>Пространство EventGo</span></div></div><div class="local-label"><i class="dot"></i>Данные сохранены на компьютере</div></div></aside><div class="app-shell"><header class="topbar"><button class="mobile-menu" data-action="menu" aria-label="Открыть меню">${icon('menu')}</button><p class="breadcrumb">Рабочее пространство <span style="margin:0 10px">/</span> <strong>${current[2]}</strong></p><div class="top-actions"><span class="top-date">${new Date().toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Yakutsk'})}</span>${eventSelect()}<button class="icon-button bell" data-action="notifications" aria-label="Уведомления${s.notifications?.unread?`: ${s.notifications.unread} новых`:''}">${icon('bell')}${s.notifications?.unread?`<span class="bell-count">${s.notifications.unread>99?'99+':s.notifications.unread}</span>`:''}</button><button class="profile" data-action="profile" aria-label="Аккаунт и настройки">${avatar(s.user.name)}<span><strong>${esc(s.user.name.split(' ')[0])}</strong><small>${isOrg()?'Организатор':'Участник команды'}</small></span>${icon('down')}</button></div></header><main class="main" id="main"></main></div>`;renderMain();}
function renderMain(){teamChat.stop();aiAssistant.stop();if(!isOrg()&&['budget','analytics','survey','catalog','messages'].includes(s.view)){$('#main').innerHTML=pageHeading('Доступ ограничен','Этот раздел доступен только организатору.');return;}const active=document.activeElement;const searchFocused=active?.matches('[data-search]'),position=active?.selectionStart;$('#main').innerHTML=(!s.data&&s.view!=='events')?`<div class="page-heading"><h1>Начнём с события</h1></div><div class="panel">${empty('Здесь будет ваше мероприятие','Создайте событие, добавьте команду и начните подготовку.',isOrg()?button('Создать событие','new-event'): '')}</div>`:({overview:overview,events:eventsView,tasks:tasksView,program:programView,guests:guestsView,team:teamView,chat:()=>pageHeading('Чат команды','Обсуждайте подготовку мероприятия в одном месте.')+teamChat.view(s.data.event),assistant:()=>pageHeading('ИИ-ассистент','Вопросы, идеи и помощь с подготовкой события.')+aiAssistant.view(s.data.event,s.user),files:filesView,budget:budgetView,calendar:calendarView,analytics:analyticsView,survey:surveyView,catalog:catalogView,messages:messagesView}[s.view]||overview)();if(s.view==='messages'&&s.data&&s.outbox?.eventId!==s.eventId)loadOutbox();if(s.view==='survey'&&s.data)loadSurvey();if(s.view==='analytics'&&s.analyticsScope==='all'&&!s.portfolioFresh){s.portfolioFresh=true;loadPortfolio();}if(s.view==='catalog'&&s.data&&!s.catalog)loadCatalog();if(s.view==='chat'&&s.data)teamChat.mount(s.eventId,s.user);if(s.view==='assistant'&&s.data)aiAssistant.mount(s.eventId,s.user);if(searchFocused){const i=$('[data-search]');if(i){i.focus();i.setSelectionRange(position,position);}}}
function pageHeading(title,description,actions=''){return `<div class="page-heading"><div><p class="eyebrow">${s.view==='events'?'Ваше рабочее пространство':esc(s.data?.event.title||'EventGo')}</p><h1>${esc(title)}</h1>${description?`<p class="description">${esc(description)}</p>`:''}</div><div class="heading-actions">${actions}</div></div>`;}
function metric(label,value,note,ic,color=''){return `<div class="metric"><div class="metric-top"><span>${label}</span><span class="metric-icon ${color}">${icon(ic)}</span></div><div class="metric-value">${value}</div><p class="metric-note">${note}</p></div>`;}
function eventEnd(e){return e.ends_at||e.starts_at.slice(0,10)+'T23:59';}
function whenText(e){const time=x=>esc(x.slice(11));if(!e.ends_at)return `${dateLong(e.starts_at)} · ${time(e.starts_at)}`;return e.ends_at.slice(0,10)===e.starts_at.slice(0,10)?`${dateLong(e.starts_at)} · ${time(e.starts_at)}–${time(e.ends_at)}`:`${dateLong(e.starts_at)} ${time(e.starts_at)} — ${dateLong(e.ends_at)} ${time(e.ends_at)}`;}
function lateTask(t){return t.status!=='done'&&!!s.data?.event&&t.due_date>eventEnd(s.data.event).slice(0,10);}
function lateMark(t){return lateTask(t)?'<span class="late-note small" title="Срок позже даты мероприятия">позже события</span>':'';}
function taskRow(t){const overdue=t.status!=='done'&&t.due_date<today();const late=lateTask(t);return `<div class="task-row"><button class="task-check ${t.status==='done'?'done':''}" data-action="toggle-task" data-id="${t.id}" aria-label="${t.status==='done'?'Вернуть в работу':'Отметить выполненной'}: ${esc(t.title)}">${t.status==='done'?icon('check'):''}</button><div class="task-copy"><button class="task-name" data-action="task" data-id="${t.id}">${esc(t.title)}</button><p class="task-sub">${esc(t.assignee_name||'Без ответственного')}${late?' · <span class="late-note">срок позже события</span>':''}</p></div>${badge(overdue?'overdue':t.status,overdue?'Просрочено':undefined)}<span class="task-date ${overdue?'overdue':''}">${dateShort(t.due_date)}</span>${avatar(t.assignee_name||'?',t.assignee_id||0)}</div>`;}
function readiness(){const e=s.data.event;return `<div class="panel"><div class="panel-head"><h2>Готовность события</h2>${icon('spark')}</div><div class="readiness"><div class="ring"><svg viewBox="0 0 120 120"><circle class="track" cx="60" cy="60" r="49"/><circle class="fill" cx="60" cy="60" r="49" stroke-dasharray="${e.readiness*3.0788} 307.88"/></svg><div class="ring-number">${e.readiness}%<small>готово к старту</small></div></div><div class="readiness-copy"><strong>${e.tasks.done} из ${e.tasks.total} задач</strong><p>${e.tasks.progress} в работе<br>${e.tasks.overdue?`<span class="negative">${e.tasks.overdue} просрочено</span>`:'Все сроки под контролем'}</p></div></div><div class="deadline-strip">${icon('clock')}${daysLeft(e.starts_at)}</div></div>`;}
function plural(n,one,few,many){const word=n%10===1&&n%100!==11?one:n%10>=2&&n%10<=4&&!(n%100>=12&&n%100<=14)?few:many;return `${n} ${word}`;}
function timeLabel(x){return x?.includes('T')?x.slice(11,16):'';}
function programRange(item){const start=timeLabel(item.starts_at),end=timeLabel(item.ends_at);return end?`${start}–${end}`:start;}
function programDay(item){return item.starts_at?dateShort(item.starts_at.slice(0,10)):'';}
function programList(items,{editable=false,compact=false}={}){if(!items?.length)return '';return `<ol class="program-timeline ${compact?'compact':''}">${items.map(item=>`<li class="program-item"><div class="program-time"><strong>${esc(programRange(item))}</strong><span>${esc(programDay(item))}</span></div><div class="program-copy"><h3>${esc(item.title)}</h3>${item.speaker||item.hall?`<p class="program-meta">${item.speaker?esc(item.speaker):''}${item.speaker&&item.hall?' · ':''}${item.hall?esc(item.hall):''}</p>`:''}${!compact&&item.description?`<p class="small muted">${esc(item.description)}</p>`:''}</div>${editable&&isOrg()?`<div class="row-actions"><button class="icon-button" data-action="edit-program" data-id="${item.id}" aria-label="Изменить ${esc(item.title)}">${icon('edit')}</button></div>`:''}</li>`).join('')}</ol>`;}
function daysLeft(date){const n=Math.ceil((Date.parse(date.slice(0,10)+'T00:00:00+09:00')-Date.parse(today()+'T00:00:00+09:00'))/86400000);return n>0?`До мероприятия: ${n} ${n%10===1&&n%100!==11?'день':n%10>=2&&n%10<=4&&!(n%100>=12&&n%100<=14)?'дня':'дней'}`:n===0?'Мероприятие начинается сегодня':'Дата мероприятия уже наступила';}
function overview(){
 const {event:e,tasks,team,activities,program=[]}=s.data;
 const upcoming=tasks.filter(t=>t.status!=='done').slice(0,4);
 const programPreview=program.slice(0,4);
 const financial=isOrg()?`<section class="panel"><div class="panel-head"><h2>Бюджет под контролем</h2><button class="text-button" data-action="nav" data-view="budget">Подробнее ${icon('arrow')}</button></div>${e.expense.actual>e.budget?`<div class="alert">Бюджет превышен на ${money(e.expense.actual-e.budget)}.</div>`:e.expense.planned>e.budget?`<div class="alert">Плановые расходы превышают бюджет на ${money(e.expense.planned-e.budget)}.</div>`:''}<div class="budget-preview"><div class="budget-amount"><strong>${money(e.budget-e.expense.actual)}</strong><span>остаток бюджета</span></div>${[['План',e.expense.planned,''],['Факт',e.expense.actual,'actual']].map(([label,value,cls])=>`<div class="budget-bars ${cls}"><span>${label}</span><div class="progress-track"><i style="width:${Math.min(100,value/Math.max(e.budget,e.expense.planned,1)*100)}%"></i></div><b>${money(value)}</b></div>`).join('')}</div></section>`:'';
 return `<div class="page-heading"><div><p class="eyebrow">Всё важное — перед глазами</p><h1>${esc(e.title)}</h1><div class="event-meta"><span>${icon('calendar')}${whenText(e)}</span><span>${icon('pin')}${esc(e.location)}</span>${e.owner_name?`<span>${icon('team')}${esc(e.owner_name)}</span>`:''}${badge(e.status)}</div></div><div class="heading-actions">${isOrg()?button('Добавить задачу','new-task'):'<span class="badge">Режим команды</span>'}${isOrg()&&e.owner_id===s.user.id?`<button class="icon-button" data-action="edit-event" aria-label="Настроить мероприятие">${icon('edit')}</button>`:''}</div></div>
 <div class="metric-grid">${metric('Задачи выполнены',`${e.tasks.done} <span class="muted" style="font-size:16px">/ ${e.tasks.total}</span>`,`${e.readiness}% плана подготовки`,'tasks')}${metric('В работе',e.tasks.progress,e.tasks.overdue?`<span class="warn">${e.tasks.overdue} просрочено</span>`:'Сроки под контролем','clock','orange')}${metric('Регистрации',e.guests.registered,`из ${e.capacity} мест${e.expected_guests?` · ждём ${e.expected_guests}`:''}`,'users','green')}${isOrg()?metric('Бюджет события',money(e.budget),`Потрачено <b>${money(e.expense.actual)}</b>`,'wallet','blue'):metric('Команда события',team.length,'Сотрудники и подрядчики','team','blue')}</div>
 <div class="grid-main"><div class="stack"><section class="panel"><div class="panel-head"><div><h2>Ближайшие задачи</h2><p class="sub">Небольшие шаги к большому событию</p></div><button class="text-button" data-action="nav" data-view="tasks">Все задачи ${icon('arrow')}</button></div>${upcoming.length?upcoming.map(taskRow).join(''):tasks.length?empty('Задачи выполнены','Можно добавить новые задачи для следующего этапа.'):empty('Задач пока нет','Добавьте первую задачу подготовки: что сделать, кто отвечает и к какому сроку.')}<div class="panel-foot"><span class="small muted">Осталось: ${plural(tasks.filter(t=>t.status!=='done').length,'задача','задачи','задач')}</span>${isOrg()?`<button class="text-button" data-action="new-task">${icon('plus')} Добавить задачу</button>`:''}</div></section><section class="panel"><div class="panel-head"><div><h2>Программа</h2><p class="sub">${program.length?plural(program.length,'пункт','пункта','пунктов'):'Расписание ещё не собрано'}</p></div><button class="text-button" data-action="nav" data-view="program">Открыть ${icon('arrow')}</button></div>${programPreview.length?programList(programPreview,{compact:true}):empty('Программа пуста','Добавьте секции, время и спикеров.')}</section>${financial}
 <section class="panel"><div class="panel-head"><h2>Команда события</h2><button class="text-button" data-action="nav" data-view="team">Открыть ${icon('arrow')}</button></div><div class="team-preview"><div class="avatar-stack">${team.slice(0,5).map((p,i)=>avatar(p.name,i)).join('')}</div><p>${team.filter(p=>p.kind==='team').length} в команде · ${plural(team.filter(p=>p.kind==='contractor').length,'подрядчик','подрядчика','подрядчиков')}</p></div></section></div>
 <div class="stack">${readiness()}<section class="registration-card"><h2>Ваши гости уже здесь</h2><p>Одна ссылка для регистрации. Все участники в одном списке.</p><div class="registration-numbers"><strong>${e.guests.registered}</strong><span>/ ${e.capacity} мест</span></div><div class="progress-track"><i style="width:${e.guests.registered/e.capacity*100}%"></i></div><button class="button light" data-action="registration">${icon('link')} Страница регистрации ${icon('arrow')}</button></section>
 <section class="panel"><div class="panel-head"><h2>Лента события</h2><span class="dot"></span></div>${activities.slice(0,3).map((a,i)=>`<div class="activity-row">${avatar(a.actor,i)}<div><p><strong>${esc(a.actor)}</strong> ${esc(a.text)}</p><small>${activityTime(a.created_at)}</small></div></div>`).join('')||'<p class="muted small" style="padding:20px">Действий пока нет.</p>'}</section></div></div>`;
}
function activityTime(x){return new Date(x.includes('T')?x:x.replace(' ','T')+'Z').toLocaleString('ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Yakutsk'});}
function searchBox(placeholder){return `<label class="search">${icon('search')}<input data-search value="${esc(s.search)}" placeholder="${esc(placeholder)}" aria-label="${esc(placeholder)}"></label>`;}
function matches(...texts){return !s.search||texts.join(' ').toLowerCase().includes(s.search.toLowerCase());}
function tabs(items){return `<div class="tabs">${items.map(([key,label])=>`<button class="tab ${s.filter===key?'active':''}" data-action="filter" data-filter="${key}">${label}</button>`).join('')}</div>`;}
function eventsView(){const events=s.events.filter(e=>matches(e.title,e.location)&&(s.filter==='all'||e.status===s.filter));return pageHeading('Мои мероприятия','От первой идеи до последнего гостя — всё в одном месте.',isOrg()?button('Создать событие','new-event'):'')+`<div class="toolbar">${tabs([['all','Все события'],['planning','В подготовке'],['active','Сейчас'],['finished','Завершённые']])}${searchBox('Найти мероприятие')}</div>${events.length?`<div class="event-cards">${events.map((e,i)=>`<article class="event-card"><div class="event-art ${['','orange','lime'][i%3]}">${icon(e.type==='Хакатон'?'spark':e.type==='Встреча'?'team':'calendar')}${badge(e.status)}</div><div class="event-card-body"><h2>${esc(e.title)}</h2><p>${icon('calendar')}${whenText(e)}</p><p>${icon('pin')}${esc(e.location)}</p><div class="section-gap"><div class="toolbar" style="margin-bottom:7px;font-size:10px;color:var(--muted)"><span>Готовность</span><strong>${e.readiness}%</strong></div><div class="progress-track"><i style="width:${e.readiness}%"></i></div></div><div class="event-card-bottom"><span>${e.tasks.total} задач · ${e.guests.registered} гостей</span><button class="text-button" data-action="open-event" data-id="${e.id}">Открыть ${icon('arrow')}</button></div></div></article>`).join('')}</div>`:`<div class="panel">${empty('События не найдены','Измените фильтры или создайте новое мероприятие.')}</div>`}`;}
function filteredTasks(){return s.data.tasks.filter(t=>matches(t.title,t.assignee_name,t.description)&&(s.filter==='all'||s.filter==='mine'&&t.assignee_user_id===s.user.id||s.filter==='overdue'&&t.status!=='done'&&t.due_date<today()||s.filter===t.status));}
function statusSelect(t){const enabled=isOrg()||t.assignee_user_id===s.user.id;return `<select class="status-select" data-change="task-status" data-id="${t.id}" aria-label="Статус задачи ${esc(t.title)}" ${enabled?'':'disabled'}>${['todo','progress','done'].map(x=>`<option value="${x}" ${t.status===x?'selected':''}>${labels[x]}</option>`).join('')}</select>`;}
function dayMs(d){return Date.parse(d.slice(0,10)+'T12:00:00+09:00');}
function ganttView(tasks){if(!tasks.length)return `<section class="panel">${empty('Задачи не найдены','Измените фильтр или добавьте новую задачу.')}</section>`;
 const eventDay=s.data.event.starts_at.slice(0,10),startOf=t=>{const c=(t.created_at||t.due_date).slice(0,10);return c<t.due_date?c:t.due_date;},days=tasks.flatMap(t=>[t.due_date,startOf(t)]).concat(eventDay,[today()]);
 const min=Math.min(...days.map(dayMs)),max=Math.max(...days.map(dayMs)),span=Math.max(max-min,86400000),ticks=[];
 for(let t=min;t<=max+86400000;t+=Math.max(86400000,Math.ceil(span/6/86400000)*86400000))ticks.push(new Date(t).toISOString().slice(0,10));
 return `<section class="panel gantt-panel"><div class="gantt-head"><span>Задача</span><div class="gantt-scale">${ticks.map(d=>`<span style="left:${((dayMs(d)-min)/span)*100}%">${esc(dateShort(d))}</span>`).join('')}</div></div><div class="gantt-legend"><span><i class="gantt-swatch todo"></i>Ожидание</span><span><i class="gantt-swatch progress"></i>В работе</span><span><i class="gantt-swatch done"></i>Готово</span><span><i class="gantt-swatch overdue"></i>Просрочено</span><span><i class="gantt-line today"></i>Сегодня</span><span><i class="gantt-line event"></i>День мероприятия</span></div>${tasks.map(t=>{const from=((dayMs(startOf(t))-min)/span)*100,to=((dayMs(t.due_date)-min)/span)*100,overdue=t.status!=='done'&&t.due_date<today();return `<div class="gantt-row"><button class="task-name gantt-label" data-action="task" data-id="${t.id}">${esc(t.title)}<small>${esc(t.assignee_name||'Без ответственного')}</small></button><div class="gantt-track"><i class="gantt-today" style="left:${((dayMs(today())-min)/span)*100}%"></i><i class="gantt-event" style="left:${((dayMs(eventDay)-min)/span)*100}%"></i><button type="button" class="gantt-bar ${t.status} ${overdue?'overdue':''}" style="left:${from}%;width:max(10px,${to-from}%)" data-action="task" data-id="${t.id}" aria-label="${esc(t.title)}: срок ${dateShort(t.due_date)}, ${labels[t.status]}" title="${esc(t.title)} · ${dateShort(startOf(t))} — ${dateShort(t.due_date)} · ${labels[t.status]}"></button></div><span class="gantt-due ${overdue?'negative':''}">${dateShort(t.due_date)}</span></div>`;}).join('')}</section>`;}
async function showPlanPreview(plan,sourceLabel){const total=plan.expenses.reduce((a,x)=>a+x.planned,0);openModal('План подготовки',`<p class="muted small" style="margin-bottom:14px">${esc(sourceLabel)}. Уже существующие задачи и статьи с тем же названием будут пропущены.</p><div class="plan-preview"><div><h3>Задачи · ${plan.tasks.length}</h3><ol class="plan-list">${plan.tasks.map(t=>`<li><strong>${esc(t.title)}</strong><small>${dateShort(t.due_date)} · ${t.priority==='high'?'высокий':t.priority==='low'?'низкий':'обычный'}</small></li>`).join('')||'<li class="muted">Нет задач</li>'}</ol></div><div><h3>Бюджет · ${money(total)}</h3><ol class="plan-list">${plan.expenses.map(x=>`<li><strong>${esc(x.name)}</strong><small>${esc(x.category)} · ${money(x.planned)}</small></li>`).join('')||'<li class="muted">Нет статей</li>'}</ol></div></div>`,{submit:'Добавить в мероприятие',wide:true,onSubmit:async()=>{const result=await api(`/events/${s.eventId}/plan`,'POST',{tasks:plan.tasks.map(({title,description,priority,due_date})=>({title,description,priority,days:Math.round((dayMs(due_date)-dayMs(s.data.event.starts_at))/86400000)})),expenses:plan.expenses});closeModal();await reload();toastWithWarnings(`Добавлено: задач ${result.tasks_added}, статей ${result.expenses_added}${result.skipped?` · пропущено ${result.skipped}`:''}`,result);}});}
async function planModal(){let templates=[];try{templates=await api('/templates');}catch{toast('Не удалось загрузить шаблоны',true);return;}
 openModal('План подготовки',`<p class="muted small" style="margin-bottom:14px">Выберите готовый шаблон или попросите ИИ составить план под это мероприятие. Задачи и статьи бюджета можно будет проверить перед добавлением.</p><div class="template-grid">${templates.map(t=>`<button type="button" class="template-card" data-action="apply-template" data-id="${esc(t.id)}"><strong>${esc(t.name)}</strong><span>${esc(t.description)}</span><small>${t.tasks} задач · ${t.expenses} статей · бюджет ${money(t.budget)}</small></button>`).join('')}</div><div class="divider"></div><button type="button" class="button soft" data-action="ai-plan">${icon('spark')} Составить план с помощью ИИ</button><p class="small muted" style="margin-top:10px">Нужен подключённый ключ в разделе «ИИ-ассистент». План появится на проверку, данные сайта ИИ сам не меняет.</p>`);}
async function applyTemplate(id){closeModal();const plan=await api(`/events/${s.eventId}/plan?template=${encodeURIComponent(id)}`);await showPlanPreview(plan,`Шаблон «${plan.name||id}»`);}
async function aiPlan(){closeModal();toast('ИИ готовит план…');try{const plan=await api(`/events/${s.eventId}/plan/ai`,'POST',{});await showPlanPreview(plan,'План от ИИ-ассистента');}catch(error){toast(error.message,true);}}
function tasksView(){const tasks=filteredTasks();return pageHeading('Задачи',`План подготовки · ${plural(s.data.tasks.length,'задача','задачи','задач')}`,`<div class="seg" role="group" aria-label="Вид задач">${[['list','list','Список'],['board','grid','Доска'],['gantt','chart','Гант']].map(([m,ic,l])=>`<button type="button" class="seg-btn ${s.taskMode===m?'active':''}" data-action="task-mode" data-mode="${m}" aria-pressed="${s.taskMode===m}">${icon(ic)}${l}</button>`).join('')}</div>${isOrg()?button('План подготовки','plan','spark','secondary')+button('Добавить задачу','new-task'):''}`)+`<div class="toolbar">${tabs([['all','Все'],['mine','Мои задачи'],['overdue','Просроченные'],['done','Готово']])}${searchBox('Найти задачу')}</div>${s.taskMode==='gantt'?ganttView(tasks):s.taskMode==='board'?`<div class="kanban">${['todo','progress','done'].map(status=>`<section class="kanban-column"><h3>${labels[status]}<span class="muted">${tasks.filter(t=>t.status===status).length}</span></h3>${tasks.filter(t=>t.status===status).map(t=>`<article class="kanban-card">${priority(t.priority)}<button class="task-name" data-action="task" data-id="${t.id}">${esc(t.title)}</button><div class="kanban-card-foot"><span class="task-date ${t.status!=='done'&&t.due_date<today()?'overdue':''}">${dateShort(t.due_date)} ${lateMark(t)}</span>${avatar(t.assignee_name||'?',t.assignee_id||0)}</div><div style="margin-top:10px">${statusSelect(t)}</div></article>`).join('')||'<p class="muted small" style="padding:10px">Пока нет задач</p>'}</section>`).join('')}</div>`:`<section class="panel">${tasks.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Задача</th><th>Ответственный</th><th>Срок</th><th>Приоритет</th><th>Статус</th></tr></thead><tbody>${tasks.map(t=>`<tr><td><button class="task-name" data-action="task" data-id="${t.id}">${esc(t.title)}</button></td><td>${t.assignee_name?avatar(t.assignee_name,t.assignee_id)+esc(t.assignee_name.split(' ')[0]):'<span class="muted">Не назначен</span>'}</td><td class="${t.status!=='done'&&t.due_date<today()?'negative':''}">${dateShort(t.due_date)}${lateTask(t)?`<br>${lateMark(t)}`:''}</td><td>${priority(t.priority)}</td><td>${statusSelect(t)}</td></tr>`).join('')}</tbody></table></div>`:empty('Задачи не найдены','Измените фильтр или добавьте новую задачу.')}</section>`}`;}
async function notificationsModal(){const data=await api('/notifications/seen','POST');const items=data.items;const view={task:'tasks',guests:'guests',budget:'budget'};openModal('Уведомления',items.length?`<div class="notice-list">${items.map((n,i)=>`<button type="button" class="notice-item ${n.level}" data-action="open-notification" data-index="${i}"><span class="notice-dot"></span><span><strong>${esc(n.text)}</strong><small>${esc(n.event_title)}${n.kind==='task'&&n.date?` · срок ${dateShort(n.date)}`:''}${n.unread?' · новое':''}</small></span>${icon('chevron')}</button>`).join('')}</div>`:empty('Всё спокойно','Просроченных задач, новых регистраций и перерасхода бюджета нет.'));s.noticeItems=items.map(n=>({...n,view:view[n.kind]}));s.notifications={...data,unread:items.filter(x=>x.level==='danger').length};const bell=$('.bell-count');if(bell){if(s.notifications.unread)bell.textContent=s.notifications.unread;else bell.remove();}}
async function openNotification(index){const n=s.noticeItems?.[index];if(!n)return;closeModal();if(n.kind==='budget'&&!isOrg())return;s.eventId=n.event_id;s.view=n.view;s.filter='all';s.search='';location.hash=n.view;await reload();if(n.task_id)await taskDetail(n.task_id);}
const fieldKinds={text:'Строка',choice:'Выбор из списка',checkbox:'Галочка (да / нет)'};
function formControl(f,{enforce=true}={}){const required=enforce&&f.required,mark=required?' <span aria-hidden="true">*</span>':'';
 if(f.kind==='checkbox')return `<label class="checkbox-line form-extra"><input type="checkbox" name="f${f.id}" ${required?'required':''}><span>${esc(f.label)}${mark}</span></label>`;
 if(f.kind==='choice')return `<label class="field form-extra"><span>${esc(f.label)}${mark}</span><select name="f${f.id}" ${required?'required':''}><option value="">Выберите вариант</option>${f.options.map(o=>`<option value="${esc(o)}">${esc(o)}</option>`).join('')}</select></label>`;
 return `<label class="field form-extra"><span>${esc(f.label)}${mark}</span><input name="f${f.id}" maxlength="500" ${required?'required':''}></label>`;}
function takeAnswers(p){const answers={};for(const key of Object.keys(p))if(/^f\d+$/.test(key)){answers[key.slice(1)]=p[key];delete p[key];}return answers;}
function guestAnswers(g){const fields=s.data.fields||[];const parts=fields.map(f=>{const v=g.answers?.[f.id];return v?`${f.label}: ${v}`:'';}).filter(Boolean);return parts.length?`<small class="guest-answers">${esc(parts.join(' · '))}</small>`:'';}
function formSummary(){const fields=(s.data.fields||[]).filter(f=>f.kind!=='text');if(!fields.length)return '';const guests=s.data.guests.filter(g=>g.status!=='cancelled');
 return `<section class="panel pad form-summary"><div class="panel-title-row"><h2>Ответы из формы регистрации</h2><span class="small muted">без отменённых гостей</span></div><div class="form-summary-grid">${fields.map(f=>{const values=f.kind==='checkbox'?['Да']:f.options;const counts=values.map(v=>guests.filter(g=>g.answers?.[f.id]===v).length);const blank=guests.length-counts.reduce((a,b)=>a+b,0);return `<div><h3>${esc(f.label)}</h3>${values.map((v,i)=>`<p><span>${esc(f.kind==='checkbox'?'Отметили':v)}</span><strong>${counts[i]}</strong></p>`).join('')}${blank?`<p class="muted"><span>${f.kind==='checkbox'?'Не отметили':'Без ответа'}</span><strong>${blank}</strong></p>`:''}</div>`;}).join('')}</div></section>`;}
function formFieldBlock(f,i){return `<div class="survey-q" data-kind="${f.kind}" ${f.id?`data-id="${f.id}"`:''}><div class="survey-q-head"><strong>Поле ${i+1}</strong><button type="button" class="icon-button" data-action="form-remove-field" data-index="${i}" aria-label="Удалить поле ${i+1}">${icon('trash')}</button></div><label class="field"><span>Название поля</span><input data-q="text" required maxlength="200" value="${esc(f.label)}" placeholder="Например: Размер футболки"></label><div class="form-grid"><label class="field"><span>Тип</span><select data-q="kind">${Object.entries(fieldKinds).map(([k,l])=>`<option value="${k}" ${f.kind===k?'selected':''}>${l}</option>`).join('')}</select></label><label class="checkbox-line survey-required"><input type="checkbox" data-q="required" ${f.required?'checked':''}> Обязательное</label></div><label class="field q-options"><span>Варианты — каждый с новой строки</span><textarea data-q="options" maxlength="6000">${esc((f.options||[]).join('\n'))}</textarea></label></div>`;}
function readFormFields(){return [...document.querySelectorAll('#form-fields .survey-q')].map(el=>({...(el.dataset.id?{id:Number(el.dataset.id)}:{}),label:el.querySelector('[data-q=text]').value,kind:el.querySelector('[data-q=kind]').value,options:el.querySelector('[data-q=options]').value.split('\n').map(x=>x.trim()).filter(Boolean),required:el.querySelector('[data-q=required]').checked}));}
function renderFormFields(list){$('#form-fields').innerHTML=list.length?list.map(formFieldBlock).join(''):'<p class="small muted">Дополнительных полей нет — гости заполняют только основные данные.</p>';}
function registrationFormEditor(){const fields=s.data.fields||[];const answered=s.data.guests.some(g=>Object.keys(g.answers||{}).length);openModal('Форма регистрации',`<p class="small muted">Имя, почта, телефон, организация и согласие на обработку данных есть в форме всегда. Ниже — ваши дополнительные вопросы к гостям: секция, питание, размер футболки и т. п.</p><div id="form-fields" class="survey-questions"></div>${button('Добавить поле','form-add-field','plus','secondary','type="button"')}${answered?'<p class="small muted section-gap">Если удалить поле, ответы гостей на него тоже удалятся.</p>':''}`,{submit:'Сохранить форму',wide:true,onSubmit:async()=>{await api(`/events/${s.eventId}/form`,'PUT',{fields:readFormFields()});await reload();toast('Форма регистрации сохранена');}});renderFormFields(fields);}
function guestForm(){openModal('Добавить гостя',`<div class="form-grid">${field('Имя и фамилия','name','','text',{full:true,max:120})}${field('Электронная почта','email','','email',{max:200})}${field('Телефон','phone','','tel',{required:false,max:40})}${field('Организация','company','','text',{required:false,max:160})}${field('Статус','status','confirmed','select',{options:[['confirmed','Подтверждён'],['registered','Зарегистрирован']]})}</div>${(s.data.fields||[]).length?`<div class="form-extras section-gap">${s.data.fields.map(f=>formControl(f,{enforce:false})).join('')}</div>`:''}<p class="small muted" style="margin-top:15px">Гость получит личный билет с QR-кодом — его можно показать или отправить ссылкой. Добавляйте только тех, кто согласился на участие.</p>`,{submit:'Добавить гостя',onSubmit:async form=>{const p=formObject(form);p.answers=takeAnswers(p);const result=await api('/events/'+s.eventId+'/guests','POST',p);await reload();toast('Гость добавлен');await ticketModal(result.ticket);return false;}});}
function parseCsv(text){text=text.replace(/^\ufeff/,'');const first=text.split(/\r?\n/,1)[0]||'';const delimiter=[';','\t',','].reduce((best,d)=>first.split(d).length>first.split(best).length?d:best,';');const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){cell+='"';i++;}else if(c==='"')quoted=false;else cell+=c;}else if(c==='"')quoted=true;else if(c===delimiter){row.push(cell);cell='';}else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);rows.push(row);row=[];cell='';}else cell+=c;}if(cell||row.length){row.push(cell);rows.push(row);}return rows;}
function guestRowsFromCsv(text){const rows=parseCsv(text);if(!rows.length)return [];const head=rows[0].map(x=>x.trim().toLowerCase());const find=re=>head.findIndex(h=>re.test(h));let columns={name:find(/имя|фио|name/),email:find(/почт|e-?mail/),phone:find(/тел|phone/),company:find(/орган|компан|company/)},start=1;if(columns.email<0){columns={name:0,email:1,phone:2,company:3};start=0;}return rows.slice(start).map((cells,i)=>({line:i+start+1,cells})).filter(r=>r.cells.some(x=>x.trim())).map(({line,cells})=>({line,name:(cells[columns.name]??'').trim(),email:(cells[columns.email]??'').trim(),phone:columns.phone>=0?(cells[columns.phone]??'').trim():'',company:columns.company>=0?(cells[columns.company]??'').trim():''}));}
async function readTextFile(file){const bytes=await file.arrayBuffer();try{return new TextDecoder('utf-8',{fatal:true}).decode(bytes);}catch{return new TextDecoder('windows-1251').decode(bytes);}}
function importGuestsForm(){openModal('Импорт гостей из CSV',`<div class="form-grid"><label class="field full"><span>Файл CSV · до 2000 строк <span aria-hidden="true">*</span></span><input name="file" type="file" accept=".csv,.txt,text/csv" required></label>${field('Статус гостей','status','confirmed','select',{full:true,options:[['confirmed','Подтверждён'],['registered','Зарегистрирован']]})}</div><div class="notice" style="margin-top:15px"><p class="small"><strong>Формат:</strong> столбцы «Имя», «Почта», «Телефон», «Организация». Подойдёт файл, сохранённый из Excel как «CSV (разделители — точки с запятой)». Если заголовка нет, порядок столбцов такой же.</p></div><p class="small muted" style="margin-top:12px">Повторные почты, строки с ошибками и гости сверх лимита мест будут пропущены — сайт покажет, какие именно.</p>`,{submit:'Загрузить гостей',onSubmit:async form=>{const file=form.file.files[0];if(file.size>1048576)throw new Error('Файл больше 1 МБ. Разделите список на части.');const rows=guestRowsFromCsv(await readTextFile(file));if(!rows.length)throw new Error('В файле не найдено строк с гостями.');const result=await api('/events/'+s.eventId+'/guests/import','POST',{rows,status:form.status.value});await reload();openModal('Импорт завершён',`<p style="font-size:14px"><strong>Добавлено гостей: ${result.added}</strong>${result.skipped.length?` · пропущено: ${result.skipped.length}`:''}</p>${result.skipped.length?`<div class="table-wrap section-gap"><table class="data-table"><thead><tr><th>Строка</th><th>Причина</th></tr></thead><tbody>${result.skipped.slice(0,50).map(x=>`<tr><td>${x.line}</td><td>${esc(x.reason)}</td></tr>`).join('')}</tbody></table></div>${result.skipped.length>50?`<p class="small muted" style="margin-top:10px">И ещё ${result.skipped.length-50} строк.</p>`:''}`:'<p class="small muted" style="margin-top:10px">Все строки загружены без ошибок.</p>'}`);return false;}});}
function programView(){const items=(s.data.program||[]).filter(p=>matches(p.title,p.speaker,p.hall,p.description));return pageHeading('Программа',`Расписание дня · ${plural((s.data.program||[]).length,'пункт','пункта','пунктов')}`,isOrg()?button('Добавить пункт','new-program'):'')+`<div class="toolbar">${searchBox('Найти по названию, спикеру или залу')}</div><div class="panel pad">${items.length?programList(items,{editable:true}):empty('Программа ещё не составлена','Соберите секции, время, залы и спикеров — гости увидят расписание на странице регистрации и в билете.',isOrg()?button('Добавить пункт','new-program'):'')}</div>`;}
function programForm(id){const p=id?(s.data.program||[]).find(x=>x.id===Number(id)):{};const day=s.data.event.starts_at.slice(0,10);openModal(id?'Пункт программы':'Новый пункт программы',`<div class="form-grid">${field('Название','title',p.title,'text',{full:true,max:200,placeholder:'Например, Открытие форума'})}${field('Начало','starts_at',p.starts_at||`${day}T10:00`,'datetime-local')}${field('Окончание','ends_at',p.ends_at||`${day}T11:00`,'datetime-local',{required:false})}${field('Спикер','speaker',p.speaker,'text',{required:false,max:160})}${field('Зал / площадка','hall',p.hall,'text',{required:false,max:120,placeholder:'Главный зал'})}${field('Описание','description',p.description,'textarea',{full:true,required:false,max:2000})}${field('Порядок','sort_order',p.sort_order??0,'number',{min:0})}${s.data.event.guests.registered?`<label class="checkbox-line full"><input type="checkbox" name="notify" ${id?'checked':''}>Сообщить гостям (${s.data.event.guests.registered}) об изменении: объявление в билете и письмо</label>`:''}</div>${id?`<div class="divider"></div><button type="button" class="text-button negative" data-action="delete-program" data-id="${id}">${icon('trash')} Удалить пункт</button>`:''}`,{submit:id?'Сохранить':'Добавить в программу',onSubmit:async form=>{const data=formObject(form);data.sort_order=Number(data.sort_order)||0;if(!data.ends_at)data.ends_at='';data.notify=!!form.notify?.checked;const result=await api(id?'/program/'+id:'/events/'+s.eventId+'/program',id?'PATCH':'POST',data);closeModal();await reload();toast(`${id?'Пункт обновлён':'Пункт добавлен в программу'}${data.notify?` · гостям отправлено уведомлений: ${result.sent}`:''}`);}});}
function guestsView(){const e=s.data.event,guests=s.data.guests.filter(g=>matches(g.name,g.email,g.company,...Object.values(g.answers||{}))&&(s.filter==='all'||g.status===s.filter));return pageHeading('Участники',`${e.guests.registered} регистраций из ${e.capacity} мест${e.expected_guests?` · ожидаем ${e.expected_guests} гостей`:''}`,`${isOrg()?button('Проверить билет','checkin','qr','secondary')+button('Бейджи','badges','users','secondary')+button('Форма регистрации','edit-form','file','secondary')+button('Импорт CSV','import-guests','upload','secondary')+button('Добавить гостя','new-guest','plus','secondary'):''}${button('Регистрация','registration','link')}`)+`<div class="metric-grid">${metric('Зарегистрировано',e.guests.registered,'Заявки через страницу события','users')}${metric('Подтверждено',s.data.guests.filter(g=>['confirmed','attended'].includes(g.status)).length,'Участники подтвердили участие','check','green')}${metric('Пришли на событие',e.guests.attended,'Отмечены на входе','qr','orange')}${metric('Свободных мест',Math.max(0,e.capacity-e.guests.registered),'Регистрация '+(e.registration_open?'открыта':'закрыта'),'calendar','blue')}</div><div class="toolbar">${tabs([['all','Все гости'],['registered','Новые'],['confirmed','Подтверждены'],['attended','Пришли'],['cancelled','Отменены']])}<div class="heading-actions">${searchBox(isOrg()?'Имя, почта, организация':'Имя или организация')}${isOrg()?`<a class="button secondary" href="/api/events/${e.id}/guests.csv" aria-label="Скачать участников CSV">${icon('download')} CSV</a>`:''}</div></div><div class="panel">${guests.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Участник</th>${isOrg()?'<th>Контакты</th>':''}<th>Организация</th><th>Статус</th>${isOrg()?'<th>Билет</th>':''}</tr></thead><tbody>${guests.map((g,i)=>`<tr><td>${avatar(g.name,i)}<strong>${esc(g.name)}</strong>${isOrg()?guestAnswers(g):''}</td>${isOrg()?`<td>${esc(g.email)}${g.phone?`<small>${esc(g.phone)}</small>`:''}</td>`:''}<td>${esc(g.company||'—')}</td><td>${isOrg()?`<select class="status-select" data-change="guest-status" data-id="${g.id}" data-attended="${g.status==='attended'?1:''}" aria-label="Статус гостя ${esc(g.name)}">${[...(g.status==='attended'?['attended']:[]),'registered','confirmed','cancelled'].map(x=>`<option value="${x}" ${x===g.status?'selected':''}>${labels[x]}</option>`).join('')}</select>`:badge(g.status)}</td>${isOrg()?`<td><button class="text-button" data-action="ticket" data-ticket="${g.ticket}">${icon('qr')} Билет</button></td>`:''}</tr>`).join('')}</tbody></table></div>`:empty('Первые гости ещё впереди','Поделитесь ссылкой на страницу регистрации.')}</div>${isOrg()?formSummary():''}`;}
function contractorBudgetLine(p){const x=contractorExpense(p);if(x)return `<p class="budget-link">${icon('wallet')}<span>В бюджете: план ${money(x.planned)} · факт ${money(x.actual)}</span></p>`;if(!p.cost)return `<p class="budget-link muted">${icon('wallet')}<span>Стоимость не указана</span></p>`;return `<p class="budget-link warn">${icon('wallet')}<span>Не учтено в бюджете</span><button class="text-button" data-action="contractor-budget" data-id="${p.id}">Добавить</button></p>`;}
function teamView(){const people=s.data.team.filter(p=>matches(p.name,p.role,p.service)&&(s.filter==='all'||p.kind===s.filter));return pageHeading('Команда и подрядчики','Люди, благодаря которым всё получится.',isOrg()?button('Добавить участника','new-person'): '')+`<div class="toolbar">${tabs([['all','Все'],['team','Команда'],['contractor','Подрядчики']])}${searchBox('Найти человека или компанию')}</div><div class="team-cards">${people.map((p,i)=>{const tasks=s.data.tasks.filter(t=>t.assignee_id===p.id),done=tasks.filter(t=>t.status==='done').length;return `<article class="person-card"><div class="person-card-top">${avatar(p.name,i)}${p.kind==='contractor'?badge(p.status,p.status==='active'?'В работе':p.status==='done'?'Выполнено':'Обсуждение'):badge('planning','Команда')}${isOrg()?`<button class="icon-button" data-action="edit-person" data-id="${p.id}" aria-label="Изменить ${esc(p.name)}">${icon('edit')}</button>`:''}</div><h3>${esc(p.name)}</h3><p>${esc(p.role)}</p>${p.service?`<p>${esc(p.service)}${isOrg()?' · '+money(p.cost):''}</p>`:''}${isOrg()&&p.kind==='contractor'?contractorBudgetLine(p):''}<hr><div class="contact">${icon('mail')}${p.email?`<a href="mailto:${esc(p.email)}">${esc(p.email)}</a>`:'<span class="muted">Почта не указана</span>'}</div>${p.phone?`<p class="contact">${icon('phone')}${esc(p.phone)}</p>`:''}<div class="toolbar" style="margin:18px 0 6px;font-size:10px;color:var(--muted)"><span>Выполнено задач</span><strong>${done} / ${tasks.length}</strong></div><div class="progress-track"><i style="width:${tasks.length?done/tasks.length*100:0}%"></i></div>${isOrg()&&p.kind==='team'?teamAccess(p):''}</article>`;}).join('')||empty('Никого не нашли','Измените поиск или добавьте участника.')}</div>`;}
function teamAccess(p){if(p.user_id)return `<p class="team-access ok">${icon('check')} Есть доступ к кабинету</p>`;if(p.invite_expires)return `<div class="team-access pending"><span>${icon('clock')} Приглашение ждёт ответа до ${esc(new Date(p.invite_expires).toLocaleDateString('ru-RU',{day:'numeric',month:'long'}))}</span><button class="text-button" data-action="invite-person" data-id="${p.id}">Новая ссылка</button></div>`;return `<button class="button soft slim team-invite" data-action="invite-person" data-id="${p.id}">${icon('mail')} Пригласить в кабинет</button>`;}
async function inviteModal(id){const p=s.data.team.find(x=>x.id===Number(id));const r=await api(`/team/${id}/invite`,'POST');const url=location.origin+'/invite/'+r.token;await reload();openModal('Приглашение в команду',`<p class="muted" style="font-size:13px;margin-bottom:16px">Отправьте ссылку участнику <strong>${esc(p?.name||'')}</strong> в мессенджере или по почте. ${r.existing?'У него уже есть аккаунт с почтой '+esc(p?.email||'')+' — достаточно будет ввести свой пароль.':'По ссылке он задаст пароль и войдёт под почтой '+esc(p?.email||'')+'.'}</p><label class="field"><span>Ссылка-приглашение</span><input readonly value="${esc(url)}" aria-label="Ссылка-приглашение"></label><p class="small muted" style="margin-top:10px">Ссылка одноразовая и действует до ${esc(new Date(r.expires_at).toLocaleDateString('ru-RU',{day:'numeric',month:'long'}))}. Новая ссылка отменяет предыдущую. Участник получит роль «участник команды»: задачи, файлы, чат, без бюджета и аналитики.</p><div class="heading-actions" style="justify-content:flex-start;margin-top:18px">${button('Скопировать ссылку','copy-invite','copy','','data-url="'+esc(url)+'"')}</div>`);}
async function invitePage(token){let i;try{i=await api('/invite/'+token);}catch(e){return publicError(e.message);}
 $('#app').innerHTML=`<main class="guest-page"><div class="guest-top">${brand('/')}</div><section class="panel pad invite-card"><span class="badge">Приглашение в команду</span><h1>${esc(i.event_title)}</h1><p class="muted">${esc(i.name)}, вас пригласили в команду мероприятия${i.role?` в роли «${esc(i.role)}»`:''}. Дата мероприятия: ${dateLong(i.starts_at)}</p><form id="invite-form" data-token="${esc(token)}"><label class="field"><span>Почта для входа</span><input value="${esc(i.email)}" readonly></label>${i.existing?field('Пароль от вашего аккаунта','password','','password',{max:200}):`${field('Имя','name',i.name,'text',{max:120})}<label class="field"><span>Придумайте пароль <span aria-hidden="true">*</span></span><input type="password" name="password" minlength="10" maxlength="200" required autocomplete="new-password"><small>Не короче 10 символов</small></label><label class="field"><span>Повторите пароль <span aria-hidden="true">*</span></span><input type="password" name="repeat" minlength="10" maxlength="200" required autocomplete="new-password"></label>`}<p class="form-error" role="alert"></p><button class="button" type="submit">${i.existing?'Войти и присоединиться':'Создать аккаунт и войти'} ${icon('arrow')}</button></form><p class="small muted" style="margin-top:14px">Приглашение действует до ${esc(new Date(i.expires_at).toLocaleDateString('ru-RU',{day:'numeric',month:'long'}))}.</p></section></main>`;}
document.addEventListener('submit',async event=>{const form=event.target;if(form.id!=='invite-form')return;event.preventDefault();const submit=form.querySelector('[type=submit]');if(submit.disabled)return;submit.disabled=true;form.querySelector('.form-error').textContent='';try{const p=formObject(form);if(p.repeat!==undefined&&p.repeat!==p.password)throw new Error('Пароли не совпадают.');delete p.repeat;const r=await api('/invite/'+form.dataset.token,'POST',p);localStorage.setItem('eventgo-event',String(r.event_id));location.href='/#overview';}catch(error){form.querySelector('.form-error').textContent=error.message;}finally{submit.disabled=false;}});
const catalogKinds={venue:'Площадка',contractor:'Подрядчик'},priceUnits={event:'за мероприятие',guest:'за гостя'};
function catalogEstimate(c){return Math.round(c.price*(c.price_unit==='guest'?s.data.event.capacity:1));}
function catalogFits(c){return !c.capacity||c.capacity>=s.data.event.capacity;}
function catalogTaken(c){return c.kind==='venue'?s.data.event.location===`${c.city}, ${c.name}`:s.data.team.some(p=>p.kind==='contractor'&&p.name.toLowerCase()===c.name.toLowerCase());}
function catalogView(){return `<div id="catalog-root">${s.catalog?catalogBody():pageHeading('Каталог площадок и подрядчиков','Справочник для всех организаторов.')+'<div class="panel pad muted">Загружаем каталог…</div>'}</div>`;}
async function loadCatalog(){try{s.catalog=await api('/catalog');s.compare=s.compare.filter(id=>s.catalog.some(c=>c.id===id));if(s.view!=='catalog')return;const root=$('#catalog-root');if(root)root.innerHTML=catalogBody();}catch(error){const root=$('#catalog-root');if(root)root.innerHTML=pageHeading('Каталог площадок и подрядчиков')+`<div class="panel">${empty('Не удалось загрузить каталог',error.message)}</div>`;}}
function catalogBody(){const e=s.data.event,f=s.catalogFilter,cities=[...new Set(s.catalog.map(c=>c.city))].sort((a,b)=>a.localeCompare(b,'ru'));return pageHeading('Каталог площадок и подрядчиков',`Общий справочник организаторов · ${s.catalog.length} записей`,button('Добавить в каталог','new-catalog'))+`<div class="toolbar">${tabs([['all','Все'],['venue','Площадки'],['contractor','Подрядчики']])}${searchBox('Название, категория или описание')}</div><div class="panel pad catalog-filters"><label class="field"><span>Город</span><select data-catalog-filter="city" aria-label="Город"><option value="">Все города</option>${cities.map(c=>`<option ${f.city===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label class="field"><span>Гостей не меньше</span><input type="number" min="0" step="1" data-catalog-filter="guests" value="${esc(f.guests)}" placeholder="Любое число"></label><label class="field"><span>Стоимость для события до, ₽</span><input type="number" min="0" step="1000" data-catalog-filter="price" value="${esc(f.price)}" placeholder="Без ограничения"></label><div class="catalog-filter-actions"><button class="button soft slim" data-action="catalog-fit">${icon('spark')} Под «${esc(e.title)}»</button><button class="text-button" data-action="catalog-reset">Сбросить</button></div></div><p class="small muted catalog-note">${icon('info')} Стоимость посчитана для «${esc(e.title)}»: ${e.capacity} мест. Цена «за гостя» умножается на число мест. «В событие» сразу добавляет запись в мероприятие и плановый расход в бюджет.</p><div id="catalog-results">${catalogResults()}</div>`;}
function catalogFiltered(){const f=s.catalogFilter,guests=Number(f.guests)||0,price=f.price===''?null:Number(f.price);return s.catalog.filter(c=>(s.filter==='all'||c.kind===s.filter)&&(!f.city||c.city===f.city)&&(!guests||!c.capacity||c.capacity>=guests)&&(price===null||catalogEstimate(c)<=price)&&matches(c.name,c.category,c.description,c.city,c.address));}
function catalogResults(){const list=catalogFiltered();return `${list.length?`<div class="catalog-grid">${list.map(catalogCard).join('')}</div>`:`<div class="panel">${empty('Ничего не нашли','Смягчите фильтры или добавьте свою запись в каталог.',button('Добавить в каталог','new-catalog'))}</div>`}${compareBar()}`;}
function catalogCard(c){const picked=s.compare.includes(c.id),taken=catalogTaken(c),estimate=catalogEstimate(c);return `<article class="catalog-card ${picked?'picked':''}"><div class="catalog-card-top">${badge(c.kind==='venue'?'planning':'pending',catalogKinds[c.kind])}<span class="catalog-city">${icon('pin')}${esc(c.city)}</span><button class="icon-button" data-action="edit-catalog" data-id="${c.id}" aria-label="Изменить ${esc(c.name)}">${icon('edit')}</button></div><h3>${esc(c.name)}</h3><p class="small muted">${esc(c.category)}${c.address?' · '+esc(c.address):''}</p>${c.description?`<p class="catalog-desc">${esc(c.description)}</p>`:''}<dl class="catalog-facts"><div><dt>Вместимость</dt><dd>${c.capacity?plural(c.capacity,'гость','гостя','гостей'):'Без ограничений'}</dd></div><div><dt>Цена</dt><dd>${money(c.price)} <small>${priceUnits[c.price_unit]}</small></dd></div><div><dt>Для события</dt><dd><strong>${money(estimate)}</strong></dd></div></dl>${catalogFits(c)?'':`<p class="late-note small">Меньше, чем мест на событии (${s.data.event.capacity})</p>`}<div class="catalog-actions"><label class="compare-check"><input type="checkbox" data-compare="${c.id}" ${picked?'checked':''}> Сравнить</label>${taken?`<span class="team-access ok">${icon('check')} ${c.kind==='venue'?'Выбрана':'Уже в команде'}</span>`:button('В событие','catalog-add','plus','slim',`data-id="${c.id}"`)}</div></article>`;}
function compareBar(){if(!s.compare.length)return '';const items=s.compare.map(id=>s.catalog.find(c=>c.id===id)).filter(Boolean);return `<div class="compare-bar" role="region" aria-label="Сравнение"><span><strong>Сравнение: ${items.length} из 3</strong> ${items.map(c=>`<span class="compare-chip">${esc(c.name)}<button data-action="compare-remove" data-id="${c.id}" aria-label="Убрать ${esc(c.name)} из сравнения">${icon('close')}</button></span>`).join('')}</span><span class="heading-actions"><button class="text-button" data-action="compare-clear">Очистить</button>${items.length>=2?button('Сравнить','compare-open','chart','slim'):'<span class="small muted">Отметьте ещё один вариант</span>'}</span></div>`;}
function refreshCatalog(){const box=$('#catalog-results');if(box)box.innerHTML=catalogResults();}
function compareModal(){const e=s.data.event,items=s.compare.map(id=>s.catalog.find(c=>c.id===id)).filter(Boolean);const costs=items.map(catalogEstimate),best=Math.min(...costs);const row=(label,cells)=>`<tr><th scope="row">${label}</th>${cells.join('')}</tr>`;openModal('Сравнение вариантов',`<p class="small muted" style="margin-bottom:14px">Расчёт для «${esc(e.title)}»: ${e.capacity} мест, бюджет ${money(e.budget)}, уже запланировано ${money(e.expense.planned)}.</p><div class="table-wrap"><table class="data-table compare-table"><thead><tr><th></th>${items.map(c=>`<th>${esc(c.name)}</th>`).join('')}</tr></thead><tbody>${row('Тип',items.map(c=>`<td>${catalogKinds[c.kind]} · ${esc(c.category)}</td>`))}${row('Город',items.map(c=>`<td>${esc(c.city)}${c.address?`<small>${esc(c.address)}</small>`:''}</td>`))}${row('Вместимость',items.map(c=>`<td class="${catalogFits(c)?'positive':'negative'}">${c.capacity?plural(c.capacity,'гость','гостя','гостей'):'Без ограничений'}<small>${catalogFits(c)?'Подходит':'Мест меньше, чем на событии'}</small></td>`))}${row('Цена',items.map(c=>`<td>${money(c.price)}<small>${priceUnits[c.price_unit]}</small></td>`))}${row('Стоимость для события',items.map((c,i)=>`<td class="${costs[i]===best?'compare-best':''}"><strong>${money(costs[i])}</strong>${costs[i]===best&&items.length>1?'<small>Дешевле всех</small>':''}</td>`))}${row('Доля бюджета',items.map((c,i)=>`<td class="${e.expense.planned+costs[i]>e.budget?'negative':''}">${e.budget?Math.round(costs[i]/e.budget*100):0}%${e.expense.planned+costs[i]>e.budget?'<small>Бюджет будет превышен</small>':''}</td>`))}${row('Описание',items.map(c=>`<td class="small">${esc(c.description||'—')}</td>`))}${row('Контакты',items.map(c=>`<td class="small">${esc(c.email||'—')}${c.phone?`<small>${esc(c.phone)}</small>`:''}</td>`))}${row('',items.map(c=>`<td>${catalogTaken(c)?`<span class="team-access ok">${icon('check')} ${c.kind==='venue'?'Выбрана':'Уже в команде'}</span>`:button('В событие','catalog-add','plus','slim',`data-id="${c.id}"`)}</td>`))}</tbody></table></div>`,{wide:true});}
async function addFromCatalog(id){const c=s.catalog.find(x=>x.id===Number(id));const result=await api(`/events/${s.eventId}/catalog`,'POST',{item_id:c.id});closeModal();await reload();toastWithWarnings(c.kind==='venue'?`Площадка «${c.name}» выбрана, расход ${money(result.estimate)} добавлен в бюджет`:`«${c.name}» добавлен в команду, расход ${money(result.estimate)} — в бюджет`,result);}
function catalogForm(id){const c=id?s.catalog.find(x=>x.id===Number(id)):{kind:s.filter==='contractor'?'contractor':'venue',city:'Якутск',price_unit:'event'};openModal(id?'Запись каталога':'Новая запись каталога',`<div class="form-grid">${field('Тип','kind',c.kind,'select',{options:[['venue','Площадка'],['contractor','Подрядчик']]})}${field('Город','city',c.city,'text',{max:80})}${field('Название','name',c.name,'text',{full:true,max:160})}${field('Категория','category',c.category,'text',{max:80,placeholder:'Лофт, Кейтеринг, Оборудование…',hint:'Для подрядчиков категория бюджета берётся отсюда, если совпадает.'})}${field('Вместимость, гостей','capacity',c.capacity??0,'number',{hint:'Для подрядчика 0 — без ограничений'})}${field('Цена, ₽','price',c.price??0,'number',{step:'1'})}${field('Цена указана','price_unit',c.price_unit,'select',{options:Object.entries(priceUnits)})}${field('Адрес','address',c.address,'text',{required:false,max:300})}${field('Электронная почта','email',c.email,'email',{required:false,max:200})}${field('Телефон','phone',c.phone,'tel',{required:false,max:40})}${field('Описание','description',c.description,'textarea',{full:true,required:false,max:2000})}</div>${id?`<div class="divider"></div><button type="button" class="text-button negative" data-action="delete-catalog" data-id="${id}">${icon('trash')} Удалить из каталога</button>`:''}`,{submit:id?'Сохранить':'Добавить в каталог',onSubmit:async form=>{const p=formObject(form);p.capacity=Number(p.capacity)||0;p.price=Number(p.price)||0;await api(id?'/catalog/'+id:'/catalog',id?'PATCH':'POST',p);closeModal();s.catalog=null;await reload();toast(id?'Запись обновлена':'Запись добавлена в каталог');}});}
document.addEventListener('input',event=>{const key=event.target.dataset?.catalogFilter;if(!key)return;s.catalogFilter[key]=event.target.value;refreshCatalog();});
document.addEventListener('change',event=>{const id=Number(event.target.dataset?.compare);if(!id)return;if(event.target.checked){if(s.compare.length>=3){event.target.checked=false;return toast('Сравнить можно не больше трёх вариантов',true);}s.compare.push(id);}else s.compare=s.compare.filter(x=>x!==id);refreshCatalog();});
const mailKinds={ticket:['confirmed','Билет'],announcement:['pending','Объявление'],survey:['attended','Опрос']};
const mailStatuses={demo:['registered','Демо'],pending:['pending','В очереди'],sent:['confirmed','Отправлено'],failed:['cancelled','Ошибка']};
const mailLive=()=>s.mail?.mode==='smtp';
function mailNote(o){if(!o)return '';const m=o.mail,st=o.statuses||{};if(m?.mode!=='smtp')return `<div class="demo-note">${icon('info')}<span><strong>Почта в демо-режиме.</strong> Письма никуда не отправляются: они сохраняются в журнале ниже, чтобы показать, что получит гость. Чтобы письма уходили гостям, подключите SMTP-сервер (README, раздел «Почта»).</span></div>`;return `<div class="demo-note mail-live">${icon('mail')}<span><strong>Почта подключена.</strong> Письма уходят гостям с адреса ${esc(m.from)} через ${esc(m.host)}. Отправлено: ${st.sent||0}${st.pending?`, в очереди: ${st.pending}`:''}${st.failed?`, <span class="negative">с ошибкой: ${st.failed}</span>`:''}.</span><span class="mail-actions">${st.failed?button('Повторить отправку','mail-retry','mail','secondary'):''}${button('Тестовое письмо','mail-test','mail','secondary')}</span></div>`;}
function ticketAnnouncements(list){if(!list?.length)return '';return `<section class="ticket-news" aria-label="Объявления организатора"><h2>${icon('bell')} Объявления организатора</h2>${list.map(a=>`<article class="news-item ${a.important?'important':''}">${a.important?'<strong class="news-flag">Важно</strong>':''}<p>${esc(a.text)}</p><time>${activityTime(a.created_at)}</time></article>`).join('')}</section>`;}
function messagesView(){const e=s.data.event,list=s.data.announcements||[],active=s.data.guests.filter(g=>g.status!=='cancelled').length,attended=e.guests.attended,survey=s.data.survey,o=s.outbox?.eventId===s.eventId?s.outbox:null,c=o?.counts||{},count=k=>o?c[k]||0:'…';
 return pageHeading('Информирование гостей','Объявления на странице билета и письма гостям.',button('Новое объявление','new-announcement','bell'))
 +mailNote(o)
 +`<div class="metric-grid">${metric('Объявлений',list.length,list.length?'Последнее: '+activityTime(list[0].created_at):'Гости увидят их в билете','bell')}${metric('Писем с билетом',count('ticket'),'Уходят при каждой регистрации','qr','green')}${metric('Писем с новостями',count('announcement'),'Рассылка объявлений','mail','orange')}${metric('Приглашений в опрос',count('survey'),survey?.status==='open'?'Опрос открыт':'Опрос сейчас закрыт','poll','blue')}</div>`
 +`<div class="messages-grid"><section class="panel"><div class="panel-head"><h2>Объявления в билете</h2></div>${list.length?`<div class="news-admin">${list.map(a=>`<article class="news-item ${a.important?'important':''}">${a.important?'<strong class="news-flag">Важно</strong>':''}<p>${esc(a.text)}</p><div class="news-meta"><time>${esc(a.author)} · ${activityTime(a.created_at)}</time><button class="icon-button" data-action="delete-announcement" data-id="${a.id}" aria-label="Удалить объявление">${icon('trash')}</button></div></article>`).join('')}</div>`:empty('Объявлений пока нет','Сообщите гостям о переносе зала, изменении времени или других важных деталях.',button('Написать объявление','new-announcement','bell'))}</section>`
 +`<section class="panel pad survey-mail"><h2>Рассылка опроса</h2>${survey?.status==='open'?`<p class="muted small">Каждый гость получит личную ссылку с кодом билета и сможет ответить один раз. Кто уже ответил или получил письмо, повторно его не получит.</p><div class="heading-actions survey-mail-actions">${button(`Пришедшим (${attended})`,'survey-send','mail','','data-scope="attended"')}${button(`Всем гостям (${active})`,'survey-send','users','secondary','data-scope="all"')}</div>`:`<p class="muted small">${survey?'Приём ответов в опросе сейчас закрыт.':'Опрос ещё не создан.'} Откройте приём ответов в разделе «Опрос гостей» — здесь появится рассылка.</p>${button('Перейти к опросу','nav','poll','secondary','data-view="survey"')}`}</section></div>`
 +`<section class="panel section-gap"><div class="panel-head"><div><h2>Журнал писем</h2><p class="sub">Последние 200 писем по мероприятию</p></div>${searchBox('Кому или тема письма')}</div>${o?outboxTable(o.items):'<div class="panel pad muted">Загружаем журнал…</div>'}</section>`;}
function outboxTable(items){const rows=items.filter(m=>matches(m.name,m.email,m.subject));return rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Когда</th><th>Кому</th><th>Тема</th><th>Тип</th><th>Статус</th><th></th></tr></thead><tbody>${rows.map(m=>`<tr><td>${activityTime(m.created_at)}</td><td><strong>${esc(m.name)}</strong><small>${esc(m.email)}</small></td><td>${esc(m.subject)}</td><td>${badge(...mailKinds[m.kind])}</td><td>${badge(...(mailStatuses[m.status]||mailStatuses.demo))}${m.status!=='sent'&&m.error?`<small class="negative" title="${esc(m.error)}">${esc(m.error.slice(0,70))}</small>`:''}</td><td><button class="text-button" data-action="open-mail" data-id="${m.id}">${icon('mail')} Открыть</button></td></tr>`).join('')}</tbody></table></div>`:empty('Писем пока нет','Письмо с билетом появится, когда гость зарегистрируется. Объявления и опрос можно разослать отсюда.');}
async function loadOutbox(){const eventId=s.eventId;try{const d=await api(`/events/${eventId}/outbox`);s.outbox={eventId,...d};s.mail=d.mail;if(s.view==='messages'&&s.eventId===eventId)renderMain();}catch(error){toast(error.message,true);}}
function mailModal(id){const m=s.outbox.items.find(x=>x.id===Number(id));const body=esc(m.body).replace(/https?:\/\/[^\s<]+/g,url=>`<a href="${url}" target="_blank" rel="noopener">${url}</a>`);openModal(m.subject,`<dl class="mail-head"><dt>Кому</dt><dd>${esc(m.name)} &lt;${esc(m.email)}&gt;</dd><dt>От</dt><dd>${esc(s.outbox.mail?.from_name||'EventGo')} &lt;${esc(s.outbox.mail?.from||'no-reply@eventgo.local')}&gt;</dd><dt>Создано</dt><dd>${activityTime(m.created_at)}</dd><dt>Статус</dt><dd>${badge(...(mailStatuses[m.status]||mailStatuses.demo))}</dd></dl><div class="mail-body">${body}</div><p class="small muted" style="margin-top:12px">${({demo:'Демо-режим: письмо сохранено в журнале и не отправлялось на почту.',pending:`Письмо в очереди на отправку${m.attempts?`, попыток: ${m.attempts}. Последняя ошибка: ${esc(m.error)}`:''}.`,sent:`Отправлено на почту ${m.sent_at?activityTime(m.sent_at):''}.`,failed:`Не отправлено после ${m.attempts} попыток: ${esc(m.error)}`})[m.status||'demo']}</p>`,{wide:true});}
function announcementForm(){const active=s.data.guests.filter(g=>g.status!=='cancelled').length;openModal('Новое объявление',`<div class="form-grid">${field('Текст объявления','text','','textarea',{full:true,max:1000,placeholder:'Например: секция «Технологии для города» переносится в зал А, начало в 10:30.'})}<label class="checkbox-line full"><input type="checkbox" name="important"> Важное — выделить в билете цветом</label><label class="checkbox-line full"><input type="checkbox" name="notify" checked> Отправить письмо гостям (${active})${mailLive()?'':' — в демо-режиме письма попадут в журнал'}</label></div><p class="small muted" style="margin-top:12px">Объявление сразу появится на странице билета у всех гостей.</p>`,{submit:'Опубликовать',onSubmit:async form=>{const p=formObject(form);const r=await api(`/events/${s.eventId}/announcements`,'POST',{text:p.text,important:!!p.important,notify:!!p.notify});closeModal();s.outbox=null;await reload();toast(r.sent?`Объявление опубликовано, писем ${mailLive()?'в очереди на отправку':'в журнале'}: ${r.sent}`:'Объявление опубликовано');}});}
async function sendSurvey(scope){const r=await api(`/events/${s.eventId}/survey/send`,'POST',{scope});closeModal();s.outbox=null;await reload();toast(r.sent?`Приглашения в опрос: ${r.sent}. ${mailLive()?'Письма отправляются, статус — в разделе «Рассылки»':'Письма в журнале раздела «Рассылки»'}`:'Новых получателей нет: все уже ответили или получили письмо');}
function filesView(){const files=s.data.files.filter(f=>matches(f.name,f.task_title));return pageHeading('Файлы события','Материалы и документы, которые всегда под рукой.')+`<button class="upload-zone" data-action="upload">${icon('upload')}<span>Выберите файл для загрузки<small>Документы, изображения и архивы · до 4 ГБ</small></span></button><div class="toolbar"><span class="muted small">${plural(s.data.files.length,'файл','файла','файлов')} в пространстве</span>${searchBox('Найти файл')}</div><div class="panel">${files.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Название</th><th>Задача</th><th>Кто загрузил</th><th>Размер</th><th></th></tr></thead><tbody>${files.map(f=>`<tr><td><div class="file-cell"><span class="file-type">${esc(f.name.split('.').pop().slice(0,4).toUpperCase())}</span><strong>${esc(f.name)}</strong></div></td><td>${esc(f.task_title||'Общие материалы')}</td><td>${esc(f.author.split(' ')[0])}<small>${activityTime(f.created_at)}</small></td><td>${sizeLabel(f.size)}</td><td><div class="row-actions"><a class="icon-button" href="/api/files/${f.id}" aria-label="Скачать ${esc(f.name)}">${icon('download')}</a>${isOrg()||f.created_by===s.user.id?`<button class="icon-button" data-action="delete-file" data-id="${f.id}" aria-label="Удалить файл">${icon('trash')}</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('Чистый лист для ваших материалов','Загрузите бриф, макет или смету. Файл можно связать с задачей.')}</div>`;}
function sizeLabel(n){return n>=1073741824?(n/1073741824).toFixed(2)+' ГБ':n>=1048576?(n/1048576).toFixed(1)+' МБ':n>=1024?(n/1024).toFixed(1)+' КБ':n+' Б';}
function budgetView(){const e=s.data.event;return pageHeading('Бюджет','Планируйте расходы и держите фактические затраты под контролем.',isOrg()?button('Добавить расход','new-expense'):'')+(e.expense.actual>e.budget?`<div class="alert">Бюджет превышен на ${money(e.expense.actual-e.budget)}. Проверьте статьи расходов.</div>`:e.expense.planned>e.budget?`<div class="alert">Плановые расходы превышают бюджет на ${money(e.expense.planned-e.budget)}.</div>`:'')+`<div class="metric-grid">${metric('Бюджет события',money(e.budget),'Установлен организатором','wallet')}${metric('Плановые расходы',money(e.expense.planned),'Сумма всех статей','tasks','blue')}${metric('Фактические расходы',money(e.expense.actual),'Уже потрачено','chart','orange')}${metric('Остаток',money(e.budget-e.expense.actual),`${Math.round(e.expense.actual/Math.max(e.budget,1)*100)}% бюджета использовано`,'check','green')}</div><div class="panel"><div class="panel-head"><h2>Статьи расходов</h2>${isOrg()?`<a class="text-button" href="/api/events/${e.id}/budget.csv">${icon('download')} Скачать CSV</a>`:''}</div>${s.data.expenses.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Статья расходов</th><th>Категория</th><th>План</th><th>Факт</th><th>Разница</th><th></th></tr></thead><tbody>${s.data.expenses.map(x=>{const c=x.contractor_id&&s.data.team.find(p=>p.id===x.contractor_id);return `<tr><td><strong>${esc(x.name)}</strong>${c?`<small class="expense-link">${icon('team')}Подрядчик: ${esc(c.name)}</small>`:''}</td><td><span class="muted">${esc(x.category)}</span></td><td>${money(x.planned)}</td><td>${money(x.actual)}</td><td class="${x.actual>x.planned?'negative':'positive'}">${money(x.planned-x.actual)}</td><td>${isOrg()?`<button class="icon-button" data-action="edit-expense" data-id="${x.id}" aria-label="Изменить расход ${esc(x.name)}">${icon('edit')}</button>`:''}</td></tr>`;}).join('')}<tr class="budget-total"><td colspan="2">Итого</td><td>${money(e.expense.planned)}</td><td>${money(e.expense.actual)}</td><td>${money(e.expense.planned-e.expense.actual)}</td><td></td></tr></tbody></table></div>`:empty('Расходов пока нет','Добавьте статьи расходов и укажите плановые суммы.')}</div>`;}
function calendarView(){const [year,month]=s.month.split('-').map(Number);const first=new Date(year,month-1,1),offset=(first.getDay()+6)%7;let cells='';for(let i=0;i<42;i++){const d=new Date(year,month-1,1-offset+i),key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const events=s.events.filter(e=>e.starts_at.startsWith(key));const tasks=s.data.tasks.filter(t=>t.due_date===key&&t.status!=='done');cells+=`<div class="calendar-day ${d.getMonth()!==month-1?'dim':''} ${key===today()?'today':''}"><span class="day-number">${d.getDate()}</span>${events.map(e=>`<button class="calendar-event" title="${esc(e.title)}" data-action="open-event" data-id="${e.id}">${esc(e.title)}</button>`).join('')}${tasks.map(t=>`<button class="calendar-event task" title="${esc(t.title)}" data-action="task" data-id="${t.id}">${esc(t.title)}</button>`).join('')}</div>`;}return pageHeading('Календарь','События и сроки задач текущего мероприятия.')+`<div class="panel pad"><div class="calendar-head"><h2>${first.toLocaleDateString('ru-RU',{month:'long'})} ${year}</h2><div class="heading-actions"><button class="button secondary slim" data-action="month-today">Сегодня</button><button class="icon-button" data-action="month" data-delta="-1" aria-label="Предыдущий месяц">${icon('left')}</button><button class="icon-button" data-action="month" data-delta="1" aria-label="Следующий месяц">${icon('chevron')}</button></div></div><div class="legend" style="margin-bottom:15px"><span><i></i>Мероприятия</span><span><i class="orange"></i>Сроки задач</span></div><div class="calendar">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(x=>`<div class="weekday">${x}</div>`).join('')}${cells}</div></div>`;}
const surveyStatus={draft:['todo','Черновик'],open:['done','Приём ответов открыт'],closed:['finished','Опрос закрыт']};
const surveyKinds={rating:'Оценка 1–5',choice:'Выбор варианта',text:'Свободный ответ'};
function surveyView(){return `<div id="survey-root">${pageHeading('Опрос гостей','Соберите обратную связь после мероприятия.')}<div class="panel pad muted">Загружаем опрос…</div></div>`;}
async function loadSurvey(){const eventId=s.eventId;try{const data=await api(`/events/${eventId}/survey`);if(s.view!=='survey'||s.eventId!==eventId)return;s.survey={eventId,...data};const root=$('#survey-root');if(root)root.innerHTML=surveyBody(s.survey);}catch(error){const root=$('#survey-root');if(root)root.innerHTML=pageHeading('Опрос гостей')+`<div class="panel">${empty('Не удалось загрузить опрос',error.message)}</div>`;}}
function surveyBody(d){if(!d.survey)return pageHeading('Опрос гостей','Соберите обратную связь после мероприятия.')+`<div class="panel">${empty('Опроса пока нет','Создайте короткую анкету: оценка, что понравилось и что улучшить. Ссылку на неё гости увидят в своём билете.',button('Создать опрос','new-survey'))}</div>`;
 const sv=d.survey,[cls,label]=surveyStatus[sv.status],attended=s.data.event.guests.attended,url=location.origin+'/survey/'+sv.public_token;
 const toggle=sv.status==='open'?button('Закрыть приём','survey-status','lock','secondary','data-status="closed"'):button(sv.status==='draft'?'Открыть приём ответов':'Открыть снова','survey-status','check','','data-status="open"');
 return pageHeading(sv.title,sv.description||'Обратная связь от гостей мероприятия.',`${sv.status==='open'?button('Разослать гостям','survey-send','mail','secondary'):''}${button('Изменить','edit-survey','edit','secondary')}${toggle}`)
 +`<div class="panel pad survey-share"><div>${badge(cls,label)}<p class="small muted">${sv.status==='draft'?'Гости пока не видят опрос. Откройте приём ответов, когда мероприятие закончится.':sv.status==='open'?'Ссылка на опрос показывается в билете каждого гостя. Её можно отправить и отдельно.':'Новые ответы не принимаются. Результаты сохранены.'}</p></div>${sv.status!=='draft'?`<div class="survey-link"><input readonly value="${esc(url)}" aria-label="Ссылка на опрос">${button('Скопировать','copy-survey','copy','secondary')}</div>`:''}</div>`
 +`<div class="metric-grid section-gap">${metric('Ответов',d.responses,attended?`${Math.round(d.responses/attended*100)}% от пришедших гостей`:'Гости ещё не отмечены на входе','users','green')}${metric('Средняя оценка',d.average===null?'—':String(d.average).replace('.',',')+' из 5','По первому вопросу с оценкой','check')}${metric('Вопросов',d.questions.length,'Обязательных: '+d.questions.filter(q=>q.required).length,'tasks','orange')}</div>`
 +(d.responses?d.questions.map(surveyResult).join(''):`<div class="panel section-gap">${empty('Ответов пока нет',sv.status==='open'?'Результаты появятся здесь, как только гости заполнят анкету.':'Откройте приём ответов, чтобы гости могли заполнить анкету.')}</div>`)
 +`<div class="section-gap">${button('Удалить опрос','delete-survey','trash','danger')}</div>`;}
function surveyResult(q){const head=`<h2>${esc(q.text)}</h2><p class="small muted">${surveyKinds[q.kind]} · ответов: ${q.answers}</p>`;
 if(q.kind==='rating'){const max=Math.max(...q.counts,1);return `<section class="panel pad section-gap survey-result"><div class="survey-result-head"><div>${head}</div><strong class="survey-score">${q.average===null?'—':String(q.average).replace('.',',')}</strong></div>${[5,4,3,2,1].map(n=>`<div class="chart-row"><span>${'★'.repeat(n)}</span><div class="progress-track"><i style="width:${q.counts[n-1]/max*100}%"></i></div><strong>${q.counts[n-1]}</strong></div>`).join('')}</section>`;}
 if(q.kind==='choice'){const max=Math.max(...q.counts,1);return `<section class="panel pad section-gap survey-result">${head}${q.options.map((o,i)=>`<div class="chart-row"><span>${esc(o)}</span><div class="progress-track"><i style="width:${q.counts[i]/max*100}%;background:var(--orange)"></i></div><strong>${q.counts[i]}</strong></div>`).join('')}</section>`;}
 return `<section class="panel pad section-gap survey-result">${head}${q.texts.length?`<ul class="survey-quotes">${q.texts.map(t=>`<li><p>${esc(t.value)}</p><span>${esc(activityTime(t.created_at))}</span></li>`).join('')}</ul>`:'<p class="small muted">Пока никто не ответил.</p>'}</section>`;}
function surveyTemplate(){const titles=(s.data.program||[]).map(p=>p.title).slice(0,8);return {title:'Как прошло мероприятие?',description:'Спасибо, что были с нами! Ответьте на три вопроса — это займёт минуту.',questions:[{text:'Оцените мероприятие в целом',kind:'rating',options:[],required:true},{text:'Что понравилось больше всего?',kind:'choice',options:titles.length>=2?titles:['Программа','Спикеры','Организация','Нетворкинг'],required:false},{text:'Что нам улучшить в следующий раз?',kind:'text',options:[],required:false}]};}
function surveyQuestionBlock(q,i){return `<div class="survey-q" data-kind="${q.kind}" ${q.id?`data-id="${q.id}"`:''}><div class="survey-q-head"><strong>Вопрос ${i+1}</strong><button type="button" class="icon-button" data-action="survey-remove-q" data-index="${i}" aria-label="Удалить вопрос ${i+1}">${icon('trash')}</button></div><label class="field"><span>Текст вопроса</span><input data-q="text" required maxlength="500" value="${esc(q.text)}"></label><div class="form-grid"><label class="field"><span>Тип ответа</span><select data-q="kind">${Object.entries(surveyKinds).map(([k,l])=>`<option value="${k}" ${q.kind===k?'selected':''}>${l}</option>`).join('')}</select></label><label class="checkbox-line survey-required"><input type="checkbox" data-q="required" ${q.required?'checked':''}> Обязательный</label></div><label class="field q-options"><span>Варианты ответа — каждый с новой строки</span><textarea data-q="options" maxlength="4000">${esc((q.options||[]).join('\n'))}</textarea></label></div>`;}
function readSurveyQuestions(){return [...document.querySelectorAll('#survey-questions .survey-q')].map(el=>({...(el.dataset.id?{id:Number(el.dataset.id)}:{}),text:el.querySelector('[data-q=text]').value,kind:el.querySelector('[data-q=kind]').value,options:el.querySelector('[data-q=options]').value.split('\n').map(x=>x.trim()).filter(Boolean),required:el.querySelector('[data-q=required]').checked}));}
function renderSurveyQuestions(list){$('#survey-questions').innerHTML=list.map(surveyQuestionBlock).join('');}
function surveyForm(){const d=s.survey?.survey?{...s.survey.survey,questions:s.survey.questions}:surveyTemplate();openModal(s.survey?.survey?'Изменить опрос':'Новый опрос',`${field('Название','title',d.title,'text',{max:200})}${field('Обращение к гостям','description',d.description||'','textarea',{required:false,max:2000})}<div id="survey-questions" class="survey-questions"></div>${button('Добавить вопрос','survey-add-q','plus','secondary','type="button"')}${s.survey?.responses?'<p class="small muted section-gap">Если удалить вопрос, ответы на него тоже удалятся.</p>':''}`,{submit:'Сохранить',wide:true,onSubmit:async form=>{const p=formObject(form);const result=await api(`/events/${s.eventId}/survey`,'PUT',{title:p.title,description:p.description,status:d.status||'draft',questions:readSurveyQuestions()});s.survey={eventId:s.eventId,...result};await reload();toast('Опрос сохранён');}});renderSurveyQuestions(d.questions);}
async function surveyPage(token){let d;try{d=await api('/survey/'+token);}catch(e){return publicError(e.message);}const ticket=new URLSearchParams(location.search).get('ticket')||'';const sv=d.survey;
 const control=q=>q.kind==='rating'?`<div class="rating-scale" role="radiogroup" aria-label="${esc(q.text)}">${[1,2,3,4,5].map(n=>`<label><input type="radio" name="q${q.id}" value="${n}" ${q.required?'required':''}><span>${n}</span></label>`).join('')}</div><div class="rating-hint"><span>Плохо</span><span>Отлично</span></div>`:q.kind==='choice'?`<div class="choice-list">${q.options.map(o=>`<label class="checkbox-line"><input type="radio" name="q${q.id}" value="${esc(o)}" ${q.required?'required':''}> ${esc(o)}</label>`).join('')}</div>`:`<textarea name="q${q.id}" maxlength="2000" ${q.required?'required':''} placeholder="Ваш ответ"></textarea>`;
 $('#app').innerHTML=`<main class="guest-page"><div class="guest-top">${brand('/afisha')}<a class="text-button" href="/afisha">${icon('left')} Афиша</a></div><section class="panel pad survey-public"><p class="eyebrow">${esc(sv.event_title)}</p><h1>${esc(sv.title)}</h1>${sv.description?`<p class="muted">${esc(sv.description)}</p>`:''}${sv.status!=='open'?`<div class="section-gap">${empty('Опрос закрыт','Организатор больше не принимает ответы. Спасибо за интерес!')}</div>`:`<form id="survey-form" data-token="${token}" data-ticket="${esc(ticket)}">${d.questions.map((q,i)=>`<fieldset class="survey-field"><legend>${i+1}. ${esc(q.text)}${q.required?' <span class="req">*</span>':''}</legend>${control(q)}</fieldset>`).join('')}<p class="form-error" role="alert"></p><button class="button" type="submit">Отправить ответы</button></form>`}</section></main>`;}
function surveyThanks(){$('#app').innerHTML=`<main class="guest-page"><div class="guest-top">${brand('/afisha')}<a class="text-button" href="/my-tickets">${icon('qr')} Мои билеты</a></div><section class="panel pad survey-public">${empty('Спасибо за ответы!','Ваше мнение поможет сделать следующее мероприятие ещё лучше.',`<a class="button" href="/afisha">${icon('calendar')} Другие мероприятия</a>`)}</section></main>`;}
document.addEventListener('submit',async event=>{const form=event.target;if(form.id!=='survey-form')return;event.preventDefault();const submit=form.querySelector('[type=submit]');if(submit.disabled)return;submit.disabled=true;form.querySelector('.form-error').textContent='';try{const answers={};for(const [key,value] of new FormData(form))if(key.startsWith('q'))answers[key.slice(1)]=value;await api('/survey/'+form.dataset.token,'POST',{answers,ticket:form.dataset.ticket});surveyThanks();}catch(error){form.querySelector('.form-error').textContent=error.message;}finally{submit.disabled=false;}});
document.addEventListener('change',event=>{const select=event.target.closest?.('[data-q=kind]');if(select)select.closest('.survey-q').dataset.kind=select.value;});
function analyticsTabs(){return `<div class="tabs analytics-scope" role="tablist" aria-label="Что показать">${[['event','Это событие'],['all','Все мероприятия']].map(([k,l])=>`<button class="tab ${(s.analyticsScope||'event')===k?'active':''}" role="tab" aria-selected="${(s.analyticsScope||'event')===k}" data-action="analytics-scope" data-scope="${k}">${l}</button>`).join('')}</div>`;}
function expectedNote(e){if(!e.expected_guests)return 'Не задано — укажите в параметрах события';const pct=Math.round(e.guests.registered/e.expected_guests*100);return `${e.guests.registered} зарегистрировано · ${pct}% плана · мест ${e.capacity}`;}
async function loadPortfolio(){try{s.portfolio=await api('/analytics/summary');if(s.view==='analytics'&&s.analyticsScope==='all')renderMain();}catch(error){s.portfolioFresh=false;toast(error.message,true);}}
function portfolioView(){const d=s.portfolio,head=pageHeading('Аналитика','Сводка по всем вашим мероприятиям.',`${analyticsTabs()}<a class="button secondary" href="/api/analytics/summary.csv">${icon('download')} CSV</a>`);if(!d)return head+'<div class="panel pad muted">Собираем сводку…</div>';const t=d.totals,rate=v=>String(v).replace('.',',');
 if(!d.events.length)return head+`<div class="panel">${empty('Мероприятий пока нет','Создайте первое событие — сводка появится автоматически.',button('Создать событие','new-event'))}</div>`;
 const max=Math.max(...d.events.map(e=>Math.max(e.capacity,e.registered)),1);
 return head+`<div class="metric-grid">${metric('Мероприятий',t.events,`${t.by_status.planning} в подготовке · ${t.by_status.active} идёт · ${t.by_status.finished} завершено`,'calendar')}${metric('Регистрации',t.registered,t.expected_events?`${t.registered_in_planned} из ${t.expected_guests} ожидаемых · ${Math.round(t.registered_in_planned/t.expected_guests*100)}% плана`:'Ожидаемое число гостей не задано','users','green')}${metric('Посещаемость',t.attendance_rate===null?'—':t.attendance_rate+'%',t.attendance_rate===null?'Вход на событиях ещё не отмечали':`${t.attended} пришли · по событиям, где проверяли билеты`,'qr','orange')}${metric('Расходы',money(t.actual),`В плане ${money(t.planned)} · бюджет ${money(t.budget)}`,'wallet','blue')}${metric('Задачи',`${t.tasks_done} <span class="muted" style="font-size:16px">/ ${t.tasks_total}</span>`,t.overdue_tasks?`<span class="warn">${t.overdue_tasks} просрочено</span>`:'Просроченных нет','tasks')}${metric('Оценка гостей',t.survey_average===null?'—':rate(t.survey_average)+'/5',t.survey_responses?`${plural(t.survey_responses,'ответ','ответа','ответов')} в опросах`+(t.cost_per_attendee!==null?` · ${money(t.cost_per_attendee)} на пришедшего`:''):'Ответов пока нет','poll','green')}</div>`
 +(t.over_budget?`<div class="alert">Фактические расходы превышают бюджет в ${plural(t.over_budget,'мероприятии','мероприятиях','мероприятиях')}. Подробности в таблице.</div>`:'')
 +`<section class="panel section-gap"><div class="panel-head"><div><h2>Мероприятия</h2><p class="sub">Нажмите на название, чтобы открыть событие</p></div></div><div class="table-wrap"><table class="data-table portfolio-table"><thead><tr><th>Мероприятие</th><th>Статус</th><th>Готовность</th><th>Гости</th><th>Пришли</th><th>Расходы</th><th>Оценка</th></tr></thead><tbody>${d.events.map(e=>`<tr><td><button class="task-name" data-action="open-event" data-id="${e.id}">${esc(e.title)}</button><small>${dateLong(e.starts_at)}${e.own?'':' · ведёт '+esc(e.owner_name)}</small></td><td>${badge(e.status)}</td><td><div class="mini-progress"><div class="progress-track"><i style="width:${e.readiness}%"></i></div><span>${e.readiness}%</span></div>${e.tasks.overdue?`<small class="negative">${plural(e.tasks.overdue,'задача просрочена','задачи просрочены','задач просрочено')}</small>`:''}</td><td><strong>${e.registered}</strong><small>${e.expected_guests?`ждём ${e.expected_guests} · `:''}мест ${e.capacity}</small></td><td>${e.attended||'—'}</td><td class="${e.actual>e.budget?'negative':''}">${money(e.actual)}<small>бюджет ${money(e.budget)}</small></td><td>${e.survey?`${rate(e.survey.average)}/5<small>${plural(e.survey.responses,'ответ','ответа','ответов')}</small>`:'—'}</td></tr>`).join('')}</tbody></table></div></section>`
 +`<section class="panel pad section-gap"><h2>Регистрации и план по гостям</h2><p class="small muted" style="margin:5px 0 14px">Полоса — зарегистрированные гости, тёмная отметка — ожидаемое число, вся шкала — вместимость самого большого события.</p>${d.events.map(e=>`<div class="chart-row plan-row"><span>${esc(e.title)}</span><div class="progress-track plan-track"><i style="width:${e.registered/max*100}%"></i>${e.expected_guests?`<b class="plan-mark" style="left:${e.expected_guests/max*100}%" title="Ожидаем ${e.expected_guests}"></b>`:''}</div><strong>${e.registered}${e.expected_guests?` / ${e.expected_guests}`:''}</strong></div>`).join('')}</section>`;}
function analyticsView(){if(s.analyticsScope==='all')return portfolioView();const e=s.data.event,ratio=e.guests.registered?Math.round(e.guests.attended/e.guests.registered*100):0;return pageHeading('Аналитика','Состояние подготовки и результаты в цифрах.',isOrg()?`${analyticsTabs()}<a class="button secondary" href="/api/events/${e.id}/report.csv">${icon('download')} Excel</a>${button('Отчёт PDF','report-print','file','secondary')}`:'')+`<div class="metric-grid">${metric('Готовность события',e.readiness+'%',`${e.tasks.done} задач из ${e.tasks.total} выполнено`,'check')}${metric('Просрочено задач',e.tasks.overdue,'Незавершённые задачи с истёкшим сроком','clock','blue')}${metric('Зарегистрировано',e.guests.registered,`из ${e.capacity} мест`,'users','green')}${metric('Ожидаемые гости',e.expected_guests||'—',expectedNote(e),'users','blue')}${metric('Посещаемость',ratio+'%',`${e.guests.attended} пришли из ${e.guests.registered} зарегистрированных`,'users','green')}${metric('Бюджет события',money(e.budget),`Потрачено <b class="${e.expense.actual>e.budget?'negative':'positive'}">${money(e.expense.actual)}</b> · план ${money(e.expense.planned)}`,'wallet')}${metric('Расход на гостя',money(e.guests.registered?e.expense.actual/e.guests.registered:0),'Фактические расходы / регистрации','wallet','orange')}${metric('Опрос гостей',s.data.survey?.average==null?'—':String(s.data.survey.average).replace('.',',')+'/5',s.data.survey?`${plural(s.data.survey.responses,'ответ','ответа','ответов')} · ${surveyStatus[s.data.survey.status]?.[1]||s.data.survey.status}`:'Опрос ещё не создан','poll')}</div><div class="grid-main"><section class="panel pad"><h2>Задачи по статусам</h2><p class="small muted" style="margin-top:5px">Текущее состояние подготовки</p><div class="chart-column">${(()=>{const columns=[['todo','Ожидание','orange'],['progress','В работе',''],['done','Готово','lime']].map(([key,label,cls])=>[s.data.tasks.filter(t=>t.status===key).length,label,cls]),top=Math.max(1,...columns.map(([n])=>n));return columns.map(([n,label,cls])=>`<div><b>${n}</b><div class="bar ${cls}" style="height:${Math.max(2,n/top*140)}px"></div><label>${label}</label></div>`).join('');})()}</div></section><section class="panel pad"><h2>Гости события</h2>${[['Мест (вместимость)',e.capacity],['Ожидаем гостей',e.expected_guests],['Зарегистрированы',e.guests.registered],['Пришли на событие',e.guests.attended]].map(([label,n])=>`<div class="chart-row"><span>${label}</span><div class="progress-track"><i style="width:${n/Math.max(e.capacity,e.guests.registered,1)*100}%"></i></div><strong>${n||(label==='Ожидаем гостей'?'—':0)}</strong></div>`).join('')}<p class="small muted">${e.expected_guests?`Вместимость — сколько гостей помещается, ожидаемое число — сколько реально ждём. ${e.guests.registered>=e.expected_guests?'План по гостям уже выполнен.':`До плана осталось ${e.expected_guests-e.guests.registered}.`}`:'Укажите ожидаемое число гостей в параметрах события, чтобы сравнивать план и факт.'} Посещаемость обновляется после проверки билетов на входе.</p></section></div><section class="panel pad section-gap"><h2>Расходы по категориям</h2>${s.data.expenses.length?s.data.expenses.map(x=>`<div class="chart-row"><span>${esc(x.name)}</span><div class="progress-track"><i style="width:${x.actual/Math.max(e.expense.actual,1)*100}%;background:var(--orange)"></i></div><strong style="font-size:10px;white-space:nowrap">${money(x.actual)}</strong></div>`).join(''):empty('Нет данных о расходах','Добавьте фактические расходы в разделе «Бюджет».')}</section>`;}

async function eventForm(id){const e=id?(s.data?.event?.id===Number(id)?s.data.event:s.events.find(x=>x.id===Number(id)))||{}:{};let organizers=[{id:s.user.id,name:s.user.name,email:s.user.email}],templates=[];try{organizers=await api('/organizers');}catch{}if(!id)try{templates=await api('/templates');}catch{}if(!organizers.some(o=>o.id===s.user.id))organizers=[{id:s.user.id,name:s.user.name,email:s.user.email},...organizers];const ownerId=e.owner_id||s.user.id;const canTransfer=!id||e.owner_id===s.user.id;openModal(id?'Параметры мероприятия':'Новое мероприятие',`<div class="form-grid">${field('Название','title',e.title,'text',{full:true,max:160,placeholder:'Например, IT-Форум 2026'})}${field('Тип мероприятия','type',e.type||'Форум','select',{options:['Форум','Конференция','Встреча','Хакатон','Фестиваль','Корпоративное событие','Другое'].map(x=>[x,x])})}${!id&&templates.length?field('Шаблон подготовки','template','','select',{required:false,full:true,options:[['','Без шаблона — пустое мероприятие'],...templates.map(t=>[t.id,`${t.name} · ${t.tasks} задач, ${t.expenses} статей`])],hint:'Шаблон сразу добавит задачи со сроками и типовые статьи бюджета. Их можно изменить.'}):''}${field('Дата и время · Якутск','starts_at',e.starts_at||'2026-11-20T10:00','datetime-local')}${field('Окончание · Якутск','ends_at',e.ends_at||'','datetime-local',{required:false,hint:'Для многодневных событий. Если не указать, событие завершится в конце дня начала.'})}<p class="date-warning full" data-check="event" data-event-id="${id||''}" role="status" hidden></p>${field('Место или ссылка на онлайн-площадку','location',e.location,'text',{full:true,placeholder:'Адрес площадки или ссылка'})}${field('Описание','description',e.description,'textarea',{full:true,required:false,max:5000})}${field('Цель мероприятия','goal',e.goal,'textarea',{full:true,required:false,max:2000})}${field('Количество мест (вместимость)','capacity',e.capacity||100,'number',{min:1})+field('Ожидаемое число гостей','expected_guests',e.expected_guests||'','number',{min:0,required:false,placeholder:'Например, 80',hint:'Сколько гостей реально ждёте. Обычно меньше вместимости.'})}${field('Общий бюджет, ₽','budget',e.budget??0,'number',{step:'0.01'})}${field('Статус','status',e.status||'planning','select',{options:['planning','active','finished'].map(x=>[x,labels[x]]),hint:'Меняется сам: в начале — «Идёт сейчас», после окончания — «Завершено».'})}${canTransfer?field('Ответственный организатор','owner_id',ownerId,'select',{options:organizers.map(o=>[o.id,`${o.name} · ${o.email}`]),full:true}):`<label class="field full"><span>Ответственный организатор</span><input readonly value="${esc((e.owner_name||'')+(e.owner_email?' · '+e.owner_email:''))}"></label>`}<label class="checkbox-line" style="align-self:center"><input name="registration_open" type="checkbox" ${e.registration_open===0?'':'checked'}>Регистрация гостей открыта</label>${templates.length?field('Шаблон подготовки','template','','select',{full:true,required:false,options:[['','Без шаблона — заполню сам'],...templates.map(t=>[t.id,`${t.name} · ${t.tasks} задач и ${t.expenses} статей бюджета`])],hint:'Задачи получат сроки относительно даты начала, суммы бюджета подстроятся под общий бюджет.'}):''}</div>${id?`<div class="divider"></div><button type="button" class="text-button negative" data-action="delete-event" data-id="${e.id}">${icon('trash')} Удалить мероприятие</button>`:'<p class="small muted" style="margin-top:15px">Ответственный сможет менять параметры события, команду, бюджет и гостей. Если выбрать другого организатора, он автоматически попадёт в команду.</p>'}`,{submit:id?'Сохранить':'Создать мероприятие',onSubmit:async form=>{const p=formObject(form);p.capacity=Number(p.capacity);p.expected_guests=p.expected_guests===''?0:Number(p.expected_guests);p.budget=Number(p.budget);p.registration_open=form.registration_open.checked;if(p.owner_id!==undefined)p.owner_id=Number(p.owner_id);if(!p.template)delete p.template;const result=await api('/events'+(id?'/'+id:''),id?'PATCH':'POST',p);if(!id){s.eventId=result.id;s.view='overview';location.hash='overview';}closeModal();await reload();toastWithWarnings(id?(p.owner_id&&p.owner_id!==e.owner_id?'Ответственность передана':'Мероприятие обновлено'):result.plan?`Мероприятие создано · задач ${result.plan.tasks_added}, статей бюджета ${result.plan.expenses_added}`:'Мероприятие создано',result);}});checkDates();}
function taskForm(id){const t=id?s.data.tasks.find(x=>x.id===Number(id)):{};openModal(id?'Редактировать задачу':'Новая задача',`<div class="form-grid">${field('Название задачи','title',t.title,'text',{full:true,max:200,placeholder:'Что нужно сделать?'})}${field('Описание','description',t.description,'textarea',{full:true,required:false})}${field('Ответственный','assignee_id',t.assignee_id||'','select',{required:false,options:[['','Не назначен'],...s.data.team.map(p=>[p.id,p.name])]})}${field('Срок выполнения','due_date',t.due_date||s.data.event.starts_at.slice(0,10),'date')}<p class="date-warning full" data-check="task" data-event-date="${eventEnd(s.data.event).slice(0,10)}" role="status" hidden></p>${field('Приоритет','priority',t.priority||'normal','select',{options:[['low','Низкий'],['normal','Обычный'],['high','Высокий']]})}${field('Статус','status',t.status||'todo','select',{options:['todo','progress','done'].map(x=>[x,labels[x]])})}</div>${id?`<div class="divider"></div><button type="button" class="text-button negative" data-action="delete-task" data-id="${id}">${icon('trash')} Удалить задачу</button>`:''}`,{submit:id?'Сохранить':'Добавить задачу',onSubmit:async form=>{const p=formObject(form);p.assignee_id=Number(p.assignee_id)||null;await saved(id?'/tasks/'+id:'/events/'+s.eventId+'/tasks',id?'PATCH':'POST',p,id?'Задача обновлена':'Задача добавлена');}});checkDates();}
async function taskDetail(id){const t=s.data.tasks.find(x=>x.id===Number(id));if(!t)return;const comments=await api('/tasks/'+id+'/comments');const canWrite=isOrg()||t.assignee_user_id===s.user.id;const attached=s.data.files.filter(f=>f.task_id===t.id);const overdue=t.status!=='done'&&t.due_date<today();openModal(t.title,`<div class="detail-meta">${badge(t.status)}${overdue?badge('overdue','Просрочено'):''}${priority(t.priority)}<span class="${overdue?'task-date overdue':'muted'}">${dateShort(t.due_date)}</span></div><p class="task-detail-description">${esc(t.description||'Описание пока не добавлено.')}</p><div class="detail-meta">${avatar(t.assignee_name||'?')}<span>${esc(t.assignee_name||'Ответственный не назначен')}</span>${isOrg()?`<button type="button" class="text-button" data-action="edit-task" data-id="${t.id}">${icon('edit')} Изменить</button>`:''}</div><div class="divider"></div><div class="toolbar"><h3>Вложения</h3>${canWrite?`<button type="button" class="text-button" data-action="upload" data-task="${t.id}">${icon('upload')} Добавить файл</button>`:''}</div>${attached.map(f=>`<p style="margin-top:8px;font-size:12px"><a href="/api/files/${f.id}">${icon('file')} ${esc(f.name)}</a></p>`).join('')||'<p class="small muted">Вложений пока нет.</p>'}<div class="divider"></div><h3>Комментарии · ${comments.length}</h3><div class="comment-list">${comments.map(c=>`<div class="comment">${avatar(c.author,c.user_id)}<div><strong>${esc(c.author)}</strong> <small>${activityTime(c.created_at)}</small><p>${esc(c.text)}</p></div></div>`).join('')||'<p class="small muted">Обсудите детали задачи с командой.</p>'}</div>${canWrite?field('Ваш комментарий','text','','textarea',{placeholder:'Напишите о ходе работы…',max:3000}):'<p class="notice">Изменять задачу и оставлять комментарии может её ответственный.</p>'}`,{submit:'Отправить комментарий',onSubmit:canWrite?async form=>{await api('/tasks/'+id+'/comments','POST',formObject(form));await reload(false);await taskDetail(id);toast('Комментарий добавлен');return false;}:null});}
function expenseForm(id){const x=id?s.data.expenses.find(x=>x.id===Number(id)):{};openModal(id?'Редактировать расход':'Новая статья расходов',`<div class="form-grid">${field('Название статьи','name',x.name,'text',{full:true,max:200})}${field('Категория','category',x.category||'Площадка','select',{full:true,options:['Площадка','Кейтеринг','Оборудование','Транспорт','Проживание','Полиграфия','Реклама','Подрядчики','Призы','Другое'].map(x=>[x,x])})}${field('Плановая сумма, ₽','planned',x.planned??0,'number',{step:'0.01'})}${field('Фактическая сумма, ₽','actual',x.actual??0,'number',{step:'0.01'})}${(()=>{const c=x.contractor_id&&s.data.team.find(p=>p.id===x.contractor_id);return c?`<p class="small muted full">Статья связана с подрядчиком «${esc(c.name)}»: изменение плановой суммы поменяет стоимость в его карточке.</p>`:'';})()}</div>${id?`<div class="divider"></div><button type="button" class="text-button negative" data-action="delete-expense" data-id="${id}">${icon('trash')} Удалить статью</button>`:''}`,{submit:id?'Сохранить':'Добавить расход',onSubmit:async form=>{const p=formObject(form);p.planned=Number(p.planned);p.actual=Number(p.actual);await saved(id?'/expenses/'+id:'/events/'+s.eventId+'/expenses',id?'PATCH':'POST',p);}});}
function personForm(id){const p=id?s.data.team.find(x=>x.id===Number(id)):{};openModal(id?'Участник команды':'Добавить в команду',`<div class="form-grid">${field('Имя или название компании','name',p.name,'text',{full:true,max:120})}${field('Тип','kind',p.kind||'team','select',{options:[['team','Участник команды'],['contractor','Подрядчик']]})}${field('Роль / зона ответственности','role',p.role,'text',{max:120})}${field('Электронная почта','email',p.email,'email',{required:false,max:200})}${field('Телефон','phone',p.phone,'tel',{required:false,max:40})}${field('Услуга подрядчика','service',p.service,'text',{full:true,required:false})}${field('Стоимость услуги, ₽','cost',p.cost??0,'number',{step:'0.01'})}${field('Статус взаимодействия','status',p.status||'active','select',{options:[['active','В работе'],['pending','Обсуждение'],['done','Выполнено']]})}${contractorBudgetFields(p)}</div><p class="small muted" style="margin-top:15px">Для доступа через аккаунт команды укажите team@eventgo.local. Другие контакты хранятся в карточке без создания учётной записи.</p>${id&&p.user_id!==s.user.id?`<div class="divider"></div><button type="button" class="text-button negative" data-action="delete-person" data-id="${id}">${icon('trash')} Удалить участника</button>`:''}`,{submit:id?'Сохранить':'Добавить участника',onSubmit:async form=>{const data=formObject(form);data.cost=Number(data.cost);data.in_budget=form.in_budget.checked;const result=await api(id?'/team/'+id:'/events/'+s.eventId+'/team',id?'PATCH':'POST',data);closeModal();await reload();toastWithWarnings(({created:'Сохранено. Стоимость добавлена в бюджет',updated:'Сохранено. Сумма в бюджете обновлена',removed:'Сохранено. Статья подрядчика убрана из бюджета',kept:'Сохранено. Статья с фактической оплатой осталась в бюджете без связи с подрядчиком'})[result.budget]||(id?'Изменения сохранены':'Участник добавлен'),result);}});const form=$('#modal form'),toggle=()=>{const on=form.kind.value==='contractor';form.querySelectorAll('[data-contractor-only]').forEach(x=>x.hidden=!on);};form.kind.addEventListener('change',toggle);toggle();}
function contractorExpense(p){return (s.data.expenses||[]).find(x=>x.contractor_id===p.id);}
function contractorBudgetFields(p){const linked=p.id?contractorExpense(p):null,checked=!p.id||!!linked;return `<div class="full contractor-budget" data-contractor-only><label class="checkbox-line"><input name="in_budget" type="checkbox" ${checked?'checked':''}>Учитывать стоимость в бюджете</label>${field('Статья бюджета','expense_category',linked?.category||'Подрядчики','select',{options:['Площадка','Кейтеринг','Оборудование','Транспорт','Проживание','Полиграфия','Реклама','Подрядчики','Призы','Другое'].map(x=>[x,x]),hint:linked?`Связано со статьёй «${linked.name}»: план ${money(linked.planned)}, факт ${money(linked.actual)}. Стоимость и план меняются вместе.`:'Плановая сумма статьи будет равна стоимости услуги и будет меняться вместе с ней.'})}</div>`;}
function confirmDelete(type,id,label){openModal('Удалить '+label+'?',`<p class="muted" style="font-size:13px">${type==='events'?'Мероприятие, задачи, гости, расходы и файлы будут удалены.':'Запись будет удалена из мероприятия.'} Это действие нельзя отменить в интерфейсе.</p>`,{submit:'Удалить',onSubmit:async()=>{const result=await api('/'+type+'/'+id,'DELETE');closeModal();if(type==='events'){s.view='events';location.hash='events';}await reload();toast(({removed:'Удалено вместе со статьёй бюджета',kept:'Удалено. Статья с фактической оплатой осталась в бюджете'})[result?.budget]||'Удалено');}});}
function registration(){const e=s.data.event,url=location.origin+'/register/'+e.public_token;openModal('Регистрация на мероприятие',`<p class="muted" style="margin-bottom:18px;font-size:13px">Поделитесь ссылкой с гостями. После заполнения формы участник получит личный билет.</p><p style="margin-bottom:18px">${badge(e.registration_open&&e.status!=='finished'?'done':'finished',e.registration_open&&e.status!=='finished'?'Регистрация открыта':'Регистрация закрыта')}</p><label class="field"><span>Ссылка для гостей</span><input readonly value="${esc(url)}" aria-label="Ссылка регистрации"></label><div class="heading-actions" style="justify-content:flex-start;margin-top:20px;flex-wrap:wrap">${button('Скопировать','copy-registration','copy')}<a class="button secondary" href="${url}" target="_blank" rel="noopener">${icon('external')} Открыть страницу</a>${isOrg()?button(e.registration_open?'Закрыть регистрацию':'Открыть регистрацию','toggle-registration',e.registration_open?'lock':'check','secondary'):''}</div><p class="small muted" style="margin-top:18px">Ссылка доступна на этом компьютере. Для других устройств используйте режим локальной сети из инструкции.</p>`);}
async function ticketModal(code){const t=await api('/ticket/'+code);openModal('Входной билет',`<div class="ticket-content"><h3>${esc(t.title)}</h3><p class="muted small">${esc(t.name)}</p><div class="ticket-qr">${qrSvg('EG:'+t.ticket)}</div>${badge(t.status)}<p class="ticket-code">EG:${t.ticket}</p><a class="button secondary" href="/ticket/${t.ticket}" target="_blank" rel="noopener">${icon('external')} Открыть билет</a></div>`);}
function upload(taskId){
 openModal('Загрузить файл',`<div class="form-grid"><label class="field full"><span>Файл · до 4 ГБ *</span><input name="file" type="file" required></label>${field('Связать с задачей','task_id',taskId||'','select',{full:true,required:false,options:[['','Общие материалы'],...s.data.tasks.map(t=>[t.id,t.title])]})}</div><div id="upload-progress" class="upload-progress" hidden><progress max="100" value="0" aria-label="Ход загрузки"></progress><p class="small muted" role="status"></p></div><p class="small muted" style="margin-top:15px">Для больших файлов оставьте окно открытым до завершения загрузки.</p>`,{submit:'Загрузить',onSubmit:async form=>{
   const file=form.file.files[0];if(file.size>MAX_FILE_BYTES)throw new Error('Максимальный размер файла — 4 ГБ (4 294 967 296 байт).');
   const url=`/api/events/${s.eventId}/files?name=${encodeURIComponent(file.name)}&task_id=${encodeURIComponent(form.task_id.value)}`;
   await new Promise((resolve,reject)=>{
     const xhr=new XMLHttpRequest();xhr.open('POST',url);xhr.timeout=2*60*60*1000;xhr.setRequestHeader('X-EventGo','1');xhr.setRequestHeader('Content-Type','application/octet-stream');
     cleanupModal=()=>{if(xhr.readyState!==4)xhr.abort();};
     const box=$('#upload-progress');box.hidden=false;
     xhr.upload.onprogress=event=>{const total=event.total||file.size;box.querySelector('progress').value=total?event.loaded/total*100:0;box.querySelector('p').textContent=event.loaded===total?'Сохраняем файл…':`Передано ${sizeLabel(event.loaded)} из ${sizeLabel(total)}`;};
     xhr.onload=()=>{cleanupModal=null;let data;try{data=JSON.parse(xhr.responseText);}catch{}if(xhr.status>=200&&xhr.status<300)resolve(data);else reject(new Error(data?.error||'Не удалось загрузить файл.'));};
     xhr.onerror=()=>{cleanupModal=null;reject(new Error('Связь с сервером прервалась. Повторите загрузку.'));};
     xhr.ontimeout=()=>{cleanupModal=null;reject(new Error('Время загрузки истекло. Повторите попытку.'));};
     xhr.onabort=()=>reject(new Error('Загрузка отменена.'));xhr.send(file);
   });
   closeModal();await reload();toast('Файл загружен');
 }});
}
function checkin(){openModal('Проверить билет',`<p class="muted small" style="margin-bottom:20px">Отсканируйте QR или вставьте код с билета. Повторный вход и отменённые билеты будут отклонены.</p>${field('Код билета или ссылка','ticket','','text',{placeholder:'EG:…',max:300})}<div id="camera"></div><button type="button" class="text-button" style="margin-top:15px" data-action="camera">${icon('qr')} Сканировать камерой</button><p class="small muted" style="margin-top:12px">Проверка для события: ${esc(s.data.event.title)}</p>`,{submit:'Проверить и отметить вход',onSubmit:async form=>{const result=await api('/events/'+s.eventId+'/checkin','POST',formObject(form));closeModal();await reload();toast('Вход отмечен: '+result.name);}});}
async function scanCamera(){if(!('BarcodeDetector'in window)||!navigator.mediaDevices?.getUserMedia){toast('Этот браузер не поддерживает сканирование. Вставьте код с билета.',true);return;}const detector=new BarcodeDetector({formats:['qr_code']});const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});const container=$('#camera');if(!container){stream.getTracks().forEach(t=>t.stop());return;}container.innerHTML='<video class="video-preview" autoplay muted playsinline aria-label="Камера для сканирования QR"></video>';const video=container.querySelector('video');video.srcObject=stream;let stopped=false;cleanupModal=()=>{stopped=true;stream.getTracks().forEach(t=>t.stop());};await video.play();const tick=async()=>{if(stopped)return;try{const codes=await detector.detect(video);if(codes.length){$('#modal-form').ticket.value=codes[0].rawValue;cleanupModal();cleanupModal=null;container.innerHTML='<p class="notice">Код считан. Нажмите «Проверить и отметить вход».</p>';return;}}catch{}if(!stopped)setTimeout(tick,300);};tick();}
function profile(){openModal('Ваш аккаунт',`<div style="display:flex;align-items:center;gap:12px">${avatar(s.user.name)}<div><h3>${esc(s.user.name)}</h3><p class="small muted">${esc(s.user.email)} · ${isOrg()?'Организатор':'Участник команды'}</p></div></div><div class="divider"></div><div class="stack" style="gap:12px;align-items:flex-start">${button('Изменить пароль','password','lock','secondary')}${isOrg()?'<a class="button secondary" href="/api/backup">'+icon('download')+' Скачать копию базы</a>':''}${button('Выйти из аккаунта','logout','logout','secondary')}</div><p class="small muted" style="margin-top:20px">В копию базы входят записи и учётные записи. Для полного переноса файлов скопируйте папку yba целиком после остановки сервера.</p>`);}
function passwordForm(){openModal('Изменить пароль',`<div class="form-grid">${field('Текущий пароль','current','','password',{full:true})}${field('Новый пароль','password','','password',{full:true,hint:'Не менее 10 символов'})}</div>`,{submit:'Изменить пароль',onSubmit:async form=>{await api('/password','POST',formObject(form));closeModal();s.user=null;renderLogin();toast('Пароль изменён. Войдите снова.');}});}
function renderLogin(){teamChat.stop();aiAssistant.stop();closeModal();$('#app').innerHTML=`<main class="login-page"><section class="login-story">${brand()}<div class="login-copy"><h1>Больше, чем<br><em>события.</em></h1><p>Идеи становятся событиями, когда у команды есть общее пространство.</p><div class="login-mini-card"><h3>${icon('check')} Всё о событии в одном месте</h3><div class="login-mini-stats"><div><strong>Задачи</strong><span>сроки и ответственные</span></div><div><strong>Гости</strong><span>регистрация и QR</span></div><div><strong>Бюджет</strong><span>план и факт</span></div></div></div></div><p class="login-tag">ПЛАНИРУЙТЕ. ОБЪЕДИНЯЙТЕ. СОЗДАВАЙТЕ.</p></section><section class="login-form-side"><div class="login-form-wrap"><h2>Рады видеть вас</h2><p>Войдите, чтобы продолжить подготовку.</p><form id="login-form">${field('Электронная почта','email','','email',{placeholder:'you@example.com',max:200})}${field('Пароль','password','','password',{placeholder:'Введите пароль',max:200})}<p class="form-error" role="alert"></p><button class="button" type="submit">Войти в пространство ${icon('arrow')}</button></form><div class="demo-box"><p>Первый раз здесь? Посмотрите готовый пример.</p><div class="demo-buttons">${button('Я организатор','demo-organizer','grid','soft')}${button('Я в команде','demo-member','team','secondary')}</div><a class="button secondary guest-entry" href="/afisha">${icon('users')} Я гость — афиша мероприятий ${icon('arrow')}</a></div><p class="login-caption">Демонстрационные аккаунты и данные подготовлены для знакомства с сервисом. Работает локально, без подключения к внешним сервисам.</p></div></section></main>`;}
async function login(data){const result=await api('/login','POST',data);s.user=result.user;await reload();window.scrollTo(0,0);}

async function guestPage(token){let result;try{result=await api('/public/'+token);}catch(e){return publicError(e.message);}const e=result.event,program=result.program||[],open=e.registration_open&&e.registered<e.capacity;$('#app').innerHTML=`<main class="guest-page"><div class="guest-top">${brand("/afisha")}<a class="text-button" href="/afisha">${icon('left')} Афиша</a></div><div class="guest-layout"><section class="guest-info"><div class="guest-hero">${badge('done',e.type)}<h1>${esc(e.title)}</h1></div><div class="event-meta"><span>${icon('calendar')}${whenText(e)} (Якутск)</span><span>${icon('pin')}${esc(e.location)}</span></div><p>${esc(e.description)}</p><p class="small muted" style="margin-top:20px">${e.capacity-e.registered>0?`Осталось ${e.capacity-e.registered} мест`:'Все места заняты'}</p>${program.length?`<div class="guest-program"><h2>Программа</h2>${programList(program,{compact:true})}</div>`:''}</section><section class="guest-form"><h2>${open?'Будем рады встрече':'Регистрация закрыта'}</h2><p>${open?'Заполните форму и получите свой билет.':'Организатор больше не принимает новые заявки.'}</p>${open?`<form id="guest-form" data-token="${token}">${field('Имя и фамилия','name','','text',{placeholder:'Как к вам обращаться?',max:120})}${field('Электронная почта','email','','email',{placeholder:'name@example.com',max:200})}${field('Телефон','phone','','tel',{required:false,max:40,placeholder:'+7 900 000-00-00'})}${field('Организация','company','','text',{required:false,max:160,placeholder:'Компания, вуз или сообщество'})}${(result.fields||[]).map(f=>formControl(f)).join('')}<label class="checkbox-line"><input type="checkbox" name="consent" required><span>Согласен на обработку указанных данных организатором для регистрации и учёта участия в этом мероприятии. <span aria-hidden="true">*</span></span></label><p class="form-error" role="alert"></p><button class="button" type="submit">Зарегистрироваться ${icon('arrow')}</button></form><p class="small muted" style="margin-top:16px;text-align:center">Билет появится сразу после регистрации.<br>Сохраните его: отправка по почте не подключена.</p>`:'<p class="notice">Если вы уже зарегистрированы, откройте сохранённую ссылку на билет или обратитесь к организатору.</p>'}</section></div></main>`;}
async function ticketPage(token){try{const t=await api('/ticket/'+token);rememberTicket(token);$('#app').innerHTML=`<main class="guest-page"><div class="guest-top">${brand("/afisha")}<a class="text-button" href="/my-tickets">${icon('qr')} Мои билеты</a></div><article class="public-ticket">${t.status==='cancelled'?'':'<span class="badge">Ваш входной билет</span>'}<h1>${esc(t.title)}</h1><h3>${esc(t.name)}</h3><p>${dateLong(t.starts_at)} · ${esc(t.starts_at.slice(11))} (Якутск)</p><p>${esc(t.location)}</p>${ticketAnnouncements(t.announcements)}${t.status==='cancelled'?`<div class="ticket-cancelled">${badge(t.status)}<h2>Регистрация отменена</h2><p class="muted">Билет больше не действует, место освобождено.</p>${t.registration_open?`<a class="button" href="/register/${esc(t.public_token)}">Зарегистрироваться снова</a>`:''}</div>`:`<div class="ticket-qr">${qrSvg('EG:'+t.ticket)}</div>${badge(t.status)}<p class="ticket-code">EG:${t.ticket}</p><p>Покажите QR-код организатору на входе.<br>Сохраните ссылку на билет или распечатайте его.</p>${button('Сохранить или распечатать','print','printer','secondary')}${t.can_cancel?`<button class="text-button ticket-cancel" data-action="cancel-ticket" data-ticket="${t.ticket}">Не смогу прийти — отменить регистрацию</button>`:''}`}${t.survey_token&&t.status!=='cancelled'?`<div class="ticket-survey"><h2>Поделитесь впечатлениями</h2><p class="muted">Организатор просит оценить мероприятие. Это займёт пару минут.</p><a class="button" href="/survey/${esc(t.survey_token)}?ticket=${esc(t.ticket)}">${icon('poll')} Пройти опрос</a></div>`:''}${(t.program||[]).length?`<div class="guest-program ticket-program"><h2>Программа</h2>${programList(t.program,{compact:true})}</div>`:''}</article></main>`;}catch(e){publicError(e.message);}}
function publicError(message){$('#app').innerHTML=`<main class="guest-page">${brand()}<div class="panel section-gap">${empty('Не удалось открыть страницу',message)}</div></main>`;}
